window.__CAT__=window.__CAT__||[];window.__CAT__.push([{"no": 124, "id": "Zx96BrlWjDY", "title": "【Lの女性向音声】小王子 七", "title_zh": "小王子 七", "duration": "00:05:55", "link": "https://www.youtube.com/watch?v=Zx96BrlWjDY", "enriched": true, "lines": [{"ts": "00:00:00", "text": "第五天，还是羊的事儿，把小王子的生活秘密一向我解开了。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:00:03", "text": "好像默默地思索了很长时间以后，得出了什么结果都一样。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:00:06", "text": "他突然没头脑地问我，羊要是吃小关幕，他也要吃花了。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:00:10", "text": "他碰到什么吃什么？", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:00:13", "text": "连有刺的话也吃吗？", "speaker": "先生", "tone": "询问", "sound": []}, {"ts": "00:00:17", "text": "有刺的也吃。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:00:20", "text": "那刺有什么用呢？", "speaker": "先生", "tone": "询问", "sound": []}, {"ts": "00:00:23", "text": "我不知道该怎么回答。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:00:27", "text": "那或着忙着要从发动机场，卸下一个宁的太近的螺丝。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:00:30", "text": "我发现机器鼓掌似乎很严重，因此也快完了。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:00:34", "text": "我担心可能会发生最坏的情况，心里挺着急的。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:00:37", "text": "那刺有什么用呢？", "speaker": "先生", "tone": "询问", "sound": []}, {"ts": "00:00:40", "text": "小王子一旦提出了问题，从来他都不会放过。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:00:44", "text": "他这那个盖子的螺丝真的很脑火。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:00:47", "text": "于是我就随便回答他一句。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:00:51", "text": "刺马什么用都没有，这纯粹是划得恶劣表现。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:00:54", "text": "可知道陈默黎一会儿。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:00:57", "text": "我这不满的心情从我说。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:01:01", "text": "我不信，划是弱小的，纯粗的。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:01:04", "text": "他总是在想方事发保护自己。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:01:08", "text": "以为有了刺就可以显出自己很厉害的样子。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:01:11", "text": "我没不做生。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:01:14", "text": "我当时想。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:01:18", "text": "如果这个螺丝再和我左对，我就云一锤子瞧掉他。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:01:21", "text": "小王子又来打扰我的思绪了。", "speaker": "先生", "tone": "责备", "sound": []}, {"ts": "00:01:25", "text": "可是你确认为话。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:01:28", "text": "算了吧，算了吧，我什么也不认为。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:01:31", "text": "我是随便回答你的。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:01:35", "text": "我现在看到我有正经事要做。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:01:38", "text": "他今晚的看着我说。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:01:42", "text": "正经事儿。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:01:45", "text": "他丑助我手拿锤子手指沾满了油屋。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:01:49", "text": "扶在一个他看来。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:01:52", "text": "丑不可严的机前上。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:01:55", "text": "你说话就和那些大人一样。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:01:59", "text": "这个话是我点难看了。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:02:02", "text": "可是他又坚可无情地说的。", "speaker": "先生", "tone": "责备", "sound": []}, {"ts": "00:02:06", "text": "你什么都分不清。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:02:09", "text": "你把什么都混在一起。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:02:12", "text": "他丑是非常浪货。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:02:16", "text": "搅动着脑袋。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:02:19", "text": "金黄的头发。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:02:23", "text": "随风产动着。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:02:26", "text": "我倒过一个星球。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:02:29", "text": "上面住过一个红脸先生。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:02:33", "text": "他从来没闻过一朵花。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:02:36", "text": "他从来没看过一颗星星。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:02:40", "text": "他什么人也没有喜欢过。", "speaker": "先生", "tone": "宠溺", "sound": []}, {"ts": "00:02:43", "text": "除了算这样以外。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:02:46", "text": "他什么也没有做过。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:02:50", "text": "他整天都你一样老是说。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:02:53", "text": "我有正经事儿。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:02:57", "text": "我是个严肃的人。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:03:00", "text": "这是他奥气是足。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:03:03", "text": "他简直不像个人。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:03:07", "text": "他是个魔固。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:03:10", "text": "他是个什么？", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:03:14", "text": "是个魔固。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:03:17", "text": "小样子当时气得脸色发白。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:03:21", "text": "几百万年以来。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:03:23", "text": "花儿都在制造这词。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:03:26", "text": "几百万年以来。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:03:29", "text": "洋人要吃花儿。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:03:32", "text": "要搞清楚为什么花儿。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:03:35", "text": "非这么大劲给自己制造。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:03:38", "text": "没有用的词。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:03:41", "text": "这难道不是正经事儿。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:03:44", "text": "难道洋和花之前的战争不重要。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:03:47", "text": "这难道不比那个大胖子红脸先生的账目更重要。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:03:50", "text": "如果我认识一朵人事件唯一的话。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:03:53", "text": "只有我的心就有它。", "speaker": "先生", "tone": "宠溺", "sound": []}, {"ts": "00:03:56", "text": "围的地方不存在。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:03:59", "text": "而这小样忽历糊涂地就把他一下子毁掉了。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:04:02", "text": "这难道不重要。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:04:05", "text": "他气得脸发红。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:04:08", "text": "然后又说着。", "speaker": "先生", "tone": "责备", "sound": []}, {"ts": "00:04:10", "text": "如果有人爱上了在这一万科星星中独一无二的一朵花。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:04:13", "text": "但他看着这些星星的时候。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:04:16", "text": "这就足以使他感到幸福。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:04:19", "text": "他可以自言自语地说。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:04:22", "text": "我的内朵花儿就在其中的一个星星上。", "speaker": "先生", "tone": "宠溺", "sound": []}, {"ts": "00:04:25", "text": "但如果洋吃掉那朵花儿。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:04:28", "text": "对他来说。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:04:31", "text": "好像所有的星星。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:04:34", "text": "一下子全都熄灭了一样。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:04:37", "text": "这难道也不重要吗？", "speaker": "先生", "tone": "询问", "sound": []}, {"ts": "00:04:40", "text": "他无法再说下去了。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:04:43", "text": "突然气不成声。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:04:46", "text": "也没尽强力。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:04:49", "text": "我放下手中的工具。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:04:52", "text": "我把吹则。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:04:55", "text": "落定。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:04:58", "text": "即刻。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:05:00", "text": "死亡。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:05:03", "text": "全部跑出脑后。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:05:06", "text": "在一个星球上。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:05:09", "text": "在我的星星上。", "speaker": "先生", "tone": "宠溺", "sound": []}, {"ts": "00:05:12", "text": "在地球上。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:05:15", "text": "有一个小王子需要安眉。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:05:18", "text": "我把他抱在怀里。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:05:21", "text": "我摇着他。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:05:24", "text": "对他说。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:05:27", "text": "你爱的那朵花儿没有威胁。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:05:30", "text": "我给你的小养化了一个照子。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:05:33", "text": "我给你的花花了一副亏家。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:05:36", "text": "我也不太知道该说些什么？", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:05:39", "text": "我觉得自己有点本着。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:05:42", "text": "我不知道怎样才能达到他的境界。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:05:45", "text": "怎样才能再进入他的境界。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:05:48", "text": "泪水世界。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:05:48", "text": "是多么神秘的。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:05:48", "text": "晚安。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:05:48", "text": "宝贝。", "speaker": "先生", "tone": "撒娇", "sound": []}], "scene": "朗读《小王子》节选（七）：小王子追问刺的用处，叙述者忙于修飞机而敷衍，二人就正经事争论花与羊孰重，最终叙述者安抚哭泣的小王子。纯文学朗读。", "behaviors": [{"desc": "朗读第五天小王子问羊是否吃花、刺有何用"}, {"desc": "叙述者修飞机分心，敷衍回答引发小王子不满"}, {"desc": "小王子动情论述花与星空的珍贵，气到哽咽"}, {"desc": "叙述者抱慰小王子，以晚安宝贝收束"}], "tone_summary": "（自动）先生视角独白，语气以平静、询问、宠溺为主，题材偏现代情侣。", "genre_tags": ["现代情侣"], "genre_main": "现代情侣", "emotion_arc": "（自动）平静", "intensity": "中", "listener_role": "（自动）被先生倾诉/照顾/管教的一方（你）", "signature_elements": [], "sensitive": false, "tier": "auto", "story": [{"type": "narr", "text": "第五天，还是关于羊的事，把小王子生活的秘密向我解开了一角。他好像默默思索了很长时间以后，得出了什么结论似的，突然没头没脑地问我：羊要是吃灌木，它也要吃花了吗？"}, {"type": "line", "speaker": "小王子", "text": "羊要是吃灌木，它也要吃花了。他碰到什么吃什么？"}, {"type": "line", "speaker": "小王子", "text": "连有刺的花也吃吗？"}, {"type": "narr", "text": "我说，有刺的也吃。"}, {"type": "line", "speaker": "小王子", "text": "那刺有什么用呢？"}, {"type": "narr", "text": "我不知道该怎么回答。当时我正忙着从发动机上卸下一个拧得太紧的螺丝。我发现机器故障似乎很严重，心里挺着急，担心会发生最坏的情况。"}, {"type": "line", "speaker": "小王子", "text": "那刺有什么用呢？"}, {"type": "narr", "text": "小王子一旦提出问题，就从来不会放过。我正为那个盖子的螺丝恼火，于是随便回答了他一句：刺什么用都没有，这纯粹是花儿的恶劣表现。"}, {"type": "narr", "text": "他沉默了一会儿，不满的心情从脸上流露出来，对我说：我不信。花是弱小的、纯真的，她总是在想方设法保护自己，以为有了刺就可以显出自己很厉害的样子。"}, {"type": "narr", "text": "我没有作声。我当时想：如果这个螺丝再和我作对，我就一锤子敲掉它。偏偏小王子又来打扰我的思绪了。"}, {"type": "line", "speaker": "小王子", "text": "可是你，却认为花——"}, {"type": "narr", "text": "我说：算了吧，算了吧，我什么也不认为，我是随便回答你的，我现在有正经事要做。他惊讶地看着我。"}, {"type": "line", "speaker": "小王子", "text": "正经事儿！"}, {"type": "narr", "text": "他看见我手拿锤子、手指沾满了油污，伏在一个在他看来丑不可言的机器上。"}, {"type": "line", "speaker": "小王子", "text": "你说话就和那些大人一样。"}, {"type": "narr", "text": "这话让我有点难堪，可他又毫不留情地说下去。"}, {"type": "line", "speaker": "小王子", "text": "你什么都分不清，你把什么都混在一起。"}, {"type": "narr", "text": "他非常愤怒，晃动着脑袋，金黄的头发随风飘动。"}, {"type": "line", "speaker": "小王子", "text": "我到过一个星球，上面住着一个红脸先生。他从来没闻过一朵花，从来没看过一颗星星，什么人也没有喜欢过。除了算账以外，他什么也没有做过。他整天都像你一样，老是说：我有正经事儿，我是个严肃的人。"}, {"type": "line", "speaker": "小王子", "text": "他傲气十足，简直不像个人，他是个蘑菇。"}, {"type": "narr", "text": "他是个什么？我问。是个蘑菇！小王子当时气得脸色发白。"}, {"type": "line", "speaker": "小王子", "text": "几百万年以来，花儿都在制造刺。几百万年以来，羊儿都在吃花。要搞清楚为什么花儿非要费这么大劲，给自己制造没有用的刺，这难道不是正经事儿？难道羊和花之间的战争不重要？这难道不比那个大胖子红脸先生的账目更重要？"}, {"type": "line", "speaker": "小王子", "text": "如果我认识一朵人世间独一无二的花，只有我的星球上有它，别的地方都不存在，而这朵花被一只羊稀里糊涂地一下子毁掉了，这难道不重要？"}, {"type": "narr", "text": "他气得脸发红，然后又说着。"}, {"type": "line", "speaker": "小王子", "text": "如果有人爱上了在这亿万颗星星中独一无二的一朵花，当他看着这些星星的时候，这就足以使他感到幸福。他可以自言自语地说：我的那朵花儿就在其中的一个星星上。"}, {"type": "line", "speaker": "小王子", "text": "但如果羊吃掉那朵花儿，对他来说，好像所有的星星一下子全都熄灭了一样。这难道也不重要吗？"}, {"type": "narr", "text": "他无法再说下去了，突然泣不成声。夜已降临，我放下手中的工具。什么锤子、螺丝钉、口渴、死亡，全都抛到脑后。在一个星球上，在我的星星上，在地球上，有一个小王子需要安慰。"}, {"type": "narr", "text": "我把他抱在怀里，摇着他，对他说：你爱的那朵花儿没有危险，我给你的小羊画了一个罩子，我给你的花画了一副盔甲。"}, {"type": "narr", "text": "我也不知道该说些什么，觉得自己有点笨拙。我不知道怎样才能达到他的境界，怎样才能再进入他的境界。泪水世界，是多么神秘的。晚安，宝贝。"}]}, {"no": 125, "id": "ZrQzOeia6LQ", "title": "【Lの女性向音声】小王子 三", "title_zh": "小王子 三", "duration": "00:03:05", "link": "https://www.youtube.com/watch?v=ZrQzOeia6LQ", "enriched": true, "lines": [{"ts": "00:00:00", "text": "我花了很长时间才弄清楚他是从哪里来的。小王子向我提出了很多问题。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "可是对我提出的问题，他好像压根没听见似的。他无意中透露了一些话，逐渐让我搞清了他的来历。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "例如他第一次看见我的飞机时，他问我：这是个什么东西？这不是什么东西，它能飞。这是飞机，是我的飞机。", "speaker": "他", "tone": "宠溺", "sound": []}, {"ts": "00:00:00", "text": "我当时很骄傲地告诉他我能飞。于是他惊讶地说道：怎么，你是从天上掉下来的？是的。我谦虚地作了回答，这真滑稽。当时小王子发出一阵清脆的笑声，这使我很不高兴。", "speaker": "他", "tone": "宠溺", "sound": []}, {"ts": "00:00:00", "text": "我要求别人严肃对待我的不幸。然后他又说道：那么你也是从天上来的？你是哪个星球上的？", "speaker": "他", "tone": "命令", "sound": []}, {"ts": "00:00:00", "text": "即刻，对于他是从哪里来的这个秘密，我隐约发现了一点线索，于是我突然问道：你是从另一个星球上来的吗？", "speaker": "他", "tone": "询问", "sound": []}, {"ts": "00:00:00", "text": "可是他不回答我的问题。他一面看着我的飞机，一面微微点点头，继续说道：可不是吗，", "speaker": "他", "tone": "询问", "sound": []}, {"ts": "00:00:00", "text": "乘坐这玩意儿，你不可能是从很远的地方来的。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "说到这里，他就长时间地陷入了沉思。然后从口袋里掏出绣花的小羊，看着他的宝贝，入了神。", "speaker": "他", "tone": "撒娇", "sound": []}, {"ts": "00:00:00", "text": "你们可以想见，这种关于别的星球的若明若暗的话语，让我心里多么好奇，因此我极力想知道其中更多的奥秘。", "speaker": "他", "tone": "命令", "sound": []}, {"ts": "00:00:00", "text": "你是从哪儿来的，小家伙？你住在什么地方？你要把我的小羊带到哪儿去？", "speaker": "他", "tone": "宠溺", "sound": []}, {"ts": "00:00:00", "text": "他沉思了一会儿，然后回答我说：幸好你们给了我一个箱子，夜晚可以给我的小羊当房子用。", "speaker": "他", "tone": "命令", "sound": []}, {"ts": "00:00:00", "text": "嗯，那当然。如果你听话的话，我再给你一根绳子，白天还可以拴住它，再加上一根杆子。", "speaker": "他", "tone": "命令", "sound": []}, {"ts": "00:00:00", "text": "我的建议看来使小王子有点反感：拴住它，多奇怪的主意。如果你不拴住它，它就会到处跑，会跑丢的。我的这位朋友又笑出了声。", "speaker": "他", "tone": "责备", "sound": []}, {"ts": "00:00:00", "text": "你想要它跑到哪儿去呀？", "speaker": "他", "tone": "撒娇", "sound": []}, {"ts": "00:00:00", "text": "不管什么地方，它一直往前跑。这是小王子郑重其事地说。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "嗯，这没什么关系，我那里很小很小。接着他略带伤感地补充了一句：", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "一直往前走，也走不出多远。", "speaker": "他", "tone": "命令", "sound": []}], "scene": "朗读《小王子》节选（三）：叙述者弄清小王子来自外星，二人聊飞机、星球与小王子珍爱的小羊，并讨论用绳子拴住小羊。纯文学朗读。", "behaviors": [{"desc": "朗读小王子初见飞机、问其来历"}, {"desc": "追问小王子来自哪颗星球，引出小羊"}, {"desc": "讨论给小羊罩子与拴绳，小王子略带伤感收束"}], "tone_summary": "（自动）他视角独白，语气以平静、命令、宠溺为主，题材偏现代情侣。", "genre_tags": ["现代情侣"], "genre_main": "现代情侣", "emotion_arc": "（自动）平静→命令", "intensity": "中偏高", "listener_role": "（自动）被他倾诉/照顾/管教的一方（你）", "signature_elements": [], "sensitive": false, "tier": "auto", "story": [{"type": "narr", "text": "我花了很长时间才弄清楚小王子是从哪里来的。他向我提出很多问题，对我问的话却像没听见。他无意间说出的几句话，渐渐让我摸清了他的来历。"}, {"type": "line", "speaker": "他", "text": "这是个什么东西？"}, {"type": "narr", "text": "他第一次看见我的飞机时这样问。我告诉他，这不是什么东西，它能飞，这是飞机，是我的飞机。我很骄傲地告诉他我能飞。"}, {"type": "line", "speaker": "他", "text": "怎么，你是从天上掉下来的？"}, {"type": "narr", "text": "我谦虚地回答了，这真滑稽。小王子发出一阵清脆的笑声，让我有些不高兴——我正希望别人严肃地对待我的不幸。"}, {"type": "line", "speaker": "他", "text": "那么你也是从天上来的？你是哪个星球上的？"}, {"type": "narr", "text": "这句话让我隐约发现了一点关于他来历的线索。我追问他是不是从另一个星球来的，他却只顾看着我的飞机，微微点头。"}, {"type": "line", "speaker": "他", "text": "可不是吗，乘坐这玩意儿，你不可能是从很远的地方来的。"}, {"type": "narr", "text": "说完，他就长时间地陷入了沉思，随后从口袋里掏出那幅画着箱子的小羊的画，看着他的宝贝，入了神。这种若明若暗的话让我心里充满好奇，我极力想知道其中的奥秘。"}, {"type": "line", "speaker": "他", "text": "你是从哪儿来的，小家伙？你住在什么地方？你要把我的小羊带到哪儿去？"}, {"type": "narr", "text": "他沉思了一会儿才回答：幸好你们给了我一个箱子，夜晚可以给我的小羊当房子用。"}, {"type": "line", "speaker": "他", "text": "嗯，那当然。如果你听话的话，我再给你一根绳子，白天还可以拴住它，再加上一根杆子。"}, {"type": "narr", "text": "这个建议显然让小王子有些反感。"}, {"type": "line", "speaker": "他", "text": "拴住它，多奇怪的主意。"}, {"type": "narr", "text": "我告诉他，如果不拴住它，它就会到处跑，会跑丢的。我的这位朋友又笑出了声。"}, {"type": "line", "speaker": "他", "text": "你想要它跑到哪儿去呀？"}, {"type": "line", "speaker": "他", "text": "不管什么地方，它一直往前跑。嗯，这没什么关系，我那里很小很小。"}, {"type": "narr", "text": "接着，他略带伤感地补充了一句："}, {"type": "line", "speaker": "他", "text": "一直往前走，也走不出多远。"}]}, {"no": 126, "id": "vDmdg5uEtds", "title": "【Lの女性向音声】小王子 九", "title_zh": "小王子 九", "duration": "00:03:37", "link": "https://www.youtube.com/watch?v=vDmdg5uEtds", "enriched": true, "lines": [{"ts": "00:00:00", "text": "我想小王子大概是利用一群野鸟迁徙的机会跑出来的。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "就在他出发的那天早上，他把他的星球收拾得整整齐齐。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "把他上头的活火山打扫得干干净净。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "他有两个活火山，早上热早点很方便。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "他还有一座死火山，他也把它打扫得干干净净。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "他想：说不定，它还会活动呢？", "speaker": "他", "tone": "询问", "sound": []}, {"ts": "00:00:00", "text": "打扫干净了，他们就可以慢慢地有规律地燃烧，而不会突然爆发。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "火山爆发就像烟囱里的火焰一样。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "当然，在我们地球上，我们人太小，不能打扫火山。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "可是火山给我们带来很多很多的麻烦。", "speaker": "他", "tone": "命令", "sound": []}, {"ts": "00:00:00", "text": "小王子还把剩下的最后几棵猴面包树苗全拔了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "他有点忧伤，他以为他再也不会回来了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "这天，这些家常活使他感到特别的亲切。", "speaker": "他", "tone": "命令", "sound": []}, {"ts": "00:00:00", "text": "当他最后一次浇花时，准备把它好好珍藏起来，", "speaker": "他", "tone": "命令", "sound": []}, {"ts": "00:00:00", "text": "他发觉自己要哭出来了。", "speaker": "他", "tone": "温柔", "sound": []}, {"ts": "00:00:00", "text": "再见了，他对花儿说到。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "可是花儿没有回答他。再见了，他又说了一遍。", "speaker": "他", "tone": "责备", "sound": []}, {"ts": "00:00:00", "text": "花儿咳嗽了一声，但并不是因为感冒，他终于对他说到：", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "我一直很蠢，请你原谅我吧，希望你能幸福。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "花儿对他毫不抱怨，他感到很惊讶。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "他举着玻璃罩子，不知该说什么才好。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "他不明白她为什么会这样的温柔恬静。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "的确，我爱你，花儿对他说到，但又因我的过错，你一点也没有理会。", "speaker": "他", "tone": "责备", "sound": []}, {"ts": "00:00:00", "text": "这已经不重要了。不过你也和我一样的蠢。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "希望你今后能够幸福。把罩子放在一边吧，我用不着了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "那要是风来了怎么办？", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "我的感冒并不那么重，夜晚的凉风对我倒有好处。我是一朵花儿。", "speaker": "他", "tone": "宠溺", "sound": []}, {"ts": "00:00:00", "text": "那要是有虫子和野兽呢？", "speaker": "他", "tone": "询问", "sound": []}, {"ts": "00:00:00", "text": "要是想认识蝴蝶，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "经不起两三只虫子是不行的。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "据说，这是很美的。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "不然，还有谁来看我呢？", "speaker": "他", "tone": "询问", "sound": []}, {"ts": "00:00:00", "text": "你就要到远方去了。至于说大动物，我并不怕，我有爪子。", "speaker": "他", "tone": "命令", "sound": []}, {"ts": "00:00:00", "text": "于是，她天真地显露出那四根刺，最后又说到：别这么磨蹭了，真烦人！", "speaker": "他", "tone": "命令", "sound": []}, {"ts": "00:00:00", "text": "你既然决定离开这儿，那就快走吧。", "speaker": "他", "tone": "责备", "sound": []}, {"ts": "00:00:00", "text": "她是怕小王子看见她在哭。她是一朵非常骄傲的花儿。", "speaker": "他", "tone": "温柔", "sound": []}, {"ts": "00:00:00", "text": "晚安。", "speaker": "他", "tone": "平静", "sound": []}], "scene": "朗读类（文学有声书）。配音者以旁白/小王子视角讲述小王子离开自己星球的过程：打扫火山、拔除最后的猴面包树幼苗，并与那朵骄傲的花儿告别。花儿在告别时吐露爱意并鼓励他远行，小王子带着忧伤离去。基调温柔伤感，主题为离别、成长与表面骄傲下的温情。无亲密或惩罚情节。", "behaviors": [{"desc": "小王子收拾星球、打扫两座火山，为离开做准备"}, {"desc": "小王子拔掉最后的猴面包树幼苗，带着不会再回来的忧伤告别"}, {"desc": "花儿向小王子道歉并表达爱意，说他与自己同样纯洁"}, {"desc": "花儿强忍眼泪催他快走，小王子离去；旁白以晚安收尾"}], "tone_summary": "（自动）他视角独白，语气以平静、命令、询问为主，题材偏现代情侣。", "genre_tags": ["现代情侣"], "genre_main": "现代情侣", "emotion_arc": "（自动）平静", "intensity": "中", "listener_role": "（自动）被他倾诉/照顾/管教的一方（你）", "signature_elements": [], "sensitive": false, "tier": "auto", "story": [{"type": "narr", "text": "我想，小王子大概是趁着一群野鸟迁徙的机会跑出来的。就在出发的那天早上，他把星球收拾得整整齐齐，把两座活火山打扫得干干净净——早上热早点很方便。那座死火山他也打扫了，想着说不定它还会活动呢。打扫干净了，它们就能慢慢地、有规律地燃烧，而不会突然爆发。"}, {"type": "narr", "text": "小王子还把剩下的最后几棵猴面包树苗全拔了。他有点忧伤，以为再也不会回来了。这天，这些家常活让他感到特别亲切。当他最后一次浇花，准备把它好好珍藏起来时，他发觉自己要哭出来了。"}, {"type": "line", "speaker": "他", "text": "再见了。"}, {"type": "narr", "text": "他对花儿说。可是花儿没有回答。他又说了一遍再见。花儿咳嗽了一声——并不是因为感冒。她终于开口了："}, {"type": "line", "speaker": "他", "text": "我一直很蠢，请你原谅我吧，希望你能幸福。"}, {"type": "narr", "text": "花儿对他毫不抱怨，他感到很惊讶。他举着玻璃罩子，不知该说什么才好，不明白她为什么这样温柔恬静。"}, {"type": "line", "speaker": "他", "text": "的确，我爱你。但因为我自己的过错，你一点也没有理会。这已经不重要了，不过你也和我一样蠢。希望你今后能够幸福。把罩子放在一边吧，我用不着了。"}, {"type": "line", "speaker": "他", "text": "那要是风来了怎么办？"}, {"type": "line", "speaker": "他", "text": "我的感冒并不那么重，夜晚的凉风对我倒有好处。我是一朵花儿。"}, {"type": "line", "speaker": "他", "text": "那要是有虫子和野兽呢？"}, {"type": "line", "speaker": "他", "text": "要是想认识蝴蝶，经不起两三只虫子是不行的。据说，这是很美的。不然，还有谁来看我呢？你就要到远方去了。至于大动物，我并不怕，我有爪子。"}, {"type": "narr", "text": "她天真地显露出那四根刺，最后又说道："}, {"type": "line", "speaker": "他", "text": "别这么磨蹭了，真烦人！你既然决定离开这儿，那就快走吧。"}, {"type": "narr", "text": "她是怕小王子看见她在哭。她是一朵非常骄傲的花儿。晚安。"}]}, {"no": 127, "id": "TOZaSCFLLvk", "title": "【Lの女性向音声】小王子 二", "title_zh": "小王子 二", "duration": "00:05:26", "link": "https://www.youtube.com/watch?v=TOZaSCFLLvk", "enriched": true, "lines": [{"ts": "00:00:00", "text": "我就这样孤独的生活著。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:03", "text": "没有一个能真正谈得来的人。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:06", "text": "一直到六年前。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:09", "text": "在三哈拉沙漠上发生那次事故。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:12", "text": "我的发动机里有个东西损坏了。", "speaker": "大人", "tone": "宠溺", "sound": []}, {"ts": "00:00:15", "text": "但是由于我既没有带机械师也没有带旅客。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:19", "text": "我就试图独自完成这个困难的维修工作。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:22", "text": "这对我来说。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:25", "text": "是个生育似的问题。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:28", "text": "我随身带的水。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:31", "text": "只够引用一个星期。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:34", "text": "第一天晚上我就睡在这远离人间烟火的大沙漠上。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:38", "text": "我比大海中附在小模牌上的云南车。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:41", "text": "还要孤独很多。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:44", "text": "而第二天附小。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:47", "text": "当你一个奇怪的小声音叫醒我是。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:50", "text": "你们可以想见我当时多么痴疾。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:54", "text": "这个小小的声音说到。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:57", "text": "请你给我画一只山羊好吗？", "speaker": "大人", "tone": "询问", "sound": []}, {"ts": "00:01:00", "text": "给我画一只羊。", "speaker": "大人", "tone": "命令", "sound": []}, {"ts": "00:01:03", "text": "我像是受到了精雷的红鸡把一下子就站了起来。", "speaker": "大人", "tone": "命令", "sound": []}, {"ts": "00:01:06", "text": "我实际的揉了揉眼睛仔细地看了看。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:01:09", "text": "我看见一个十分奇怪的小家伙。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:01:13", "text": "严肃的吵我。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:01:16", "text": "宁魔望着。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:01:19", "text": "这是后来我给他画出来的。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:01:22", "text": "最好的一幅画像。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:01:25", "text": "可是我的话当然要比他本人的模样迅速很多。", "speaker": "大人", "tone": "宠溺", "sound": []}, {"ts": "00:01:29", "text": "这不是我的过头。", "speaker": "大人", "tone": "宠溺", "sound": []}, {"ts": "00:01:32", "text": "六岁的时候。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:01:35", "text": "大人们是我对华家的生涯失去了勇气。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:01:38", "text": "除了画过开著肚皮和闭著肚皮的帽蛇。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:01:41", "text": "后来再没有学过画。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:01:44", "text": "我经济的正大的眼前看着这突然出现的小家伙。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:01:48", "text": "你们不要忘记我当时是处在远离人间千里之外的地方。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:01:51", "text": "而是个小家伙给我的印象是。", "speaker": "大人", "tone": "命令", "sound": []}, {"ts": "00:01:54", "text": "他记不像米勒路的样子。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:01:57", "text": "也没有半点的疲乏。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:02:00", "text": "鸡可惧怕的深情。", "speaker": "大人", "tone": "温柔", "sound": []}, {"ts": "00:02:04", "text": "他似乎。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:02:06", "text": "他似乎不像是一个迷失在大沙漠中的孩子。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:02:09", "text": "当我在惊讶之中。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:02:12", "text": "中又能说出话来的时候对他说。", "speaker": "大人", "tone": "责备", "sound": []}, {"ts": "00:02:15", "text": "你在这儿干什么？", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:02:18", "text": "可是他却不宽不忙的好像有一件重要的事情一般对我重复说的。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:02:21", "text": "前给我画一只山羊。", "speaker": "大人", "tone": "命令", "sound": []}, {"ts": "00:02:24", "text": "当一种神秘的东西把你震出的时候。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:02:27", "text": "你是不敢不听从他的职配的。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:02:30", "text": "在这个狂物人员的沙漠上。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:02:33", "text": "面临死亡的危险的情况下。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:02:35", "text": "尽管这样的举动让我觉得十分荒诞。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:02:38", "text": "但我还是掏出了职和笔。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:02:41", "text": "这是我有机器。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:02:44", "text": "我只学过弟弟历史。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:02:47", "text": "算数。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:02:50", "text": "与法。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:02:53", "text": "九点不太开心的对小家伙说我不会画画。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:02:56", "text": "但回答我说。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:02:59", "text": "没有关系。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:03:02", "text": "跟画一只羊吧。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:03:04", "text": "因为我从来没有画过羊。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:03:07", "text": "我就给他。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:03:10", "text": "从我仅仅会画的两幅画堂中。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:03:13", "text": "那幅。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:03:16", "text": "闭著肚皮的俱盲。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:03:19", "text": "不不要忙著。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:03:22", "text": "他肚子里还有一头像。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:03:25", "text": "我听了他的话简直木灯口袋。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:03:28", "text": "他接著说。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:03:31", "text": "俱盲这东西太危险了。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:03:33", "text": "大象。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:03:36", "text": "又太占地方。", "speaker": "大人", "tone": "责备", "sound": []}, {"ts": "00:03:39", "text": "我住的地方非常小。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:03:42", "text": "我需要一只羊。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:03:45", "text": "都要画一只羊吧。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:03:48", "text": "于是我就给他画了。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:03:51", "text": "他专心地看着最后又说。", "speaker": "大人", "tone": "责备", "sound": []}, {"ts": "00:03:54", "text": "我不要。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:03:57", "text": "这只羊已经病得很重了给我重新画一只。", "speaker": "大人", "tone": "命令", "sound": []}, {"ts": "00:04:00", "text": "我又画了起来。", "speaker": "大人", "tone": "命令", "sound": []}, {"ts": "00:04:03", "text": "我的这位朋友天真可爱的笑了。", "speaker": "大人", "tone": "宠溺", "sound": []}, {"ts": "00:04:03", "text": "并且客气的拒绝到。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:04:03", "text": "你看。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:04:03", "text": "你画的不是小羊是头宫羊还有鸡奖呢？", "speaker": "大人", "tone": "询问", "sound": []}, {"ts": "00:04:03", "text": "于是我又重新画了一场。", "speaker": "大人", "tone": "责备", "sound": []}, {"ts": "00:04:03", "text": "这幅画和前几个一样也被拒绝了。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:04:03", "text": "这只太老了。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:04:03", "text": "我想要一只能活得长的羊。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:04:03", "text": "我不耐烦了。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:04:03", "text": "因为我急于要减修发动机。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:04:03", "text": "于是嘲嘲地。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:04:03", "text": "画了这张画。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:04:03", "text": "对他说到。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:04:03", "text": "这是一个盒子。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:04:03", "text": "你要的羊就在里面。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:04:03", "text": "当时我十分惊奇的。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:04:03", "text": "看到我的这位小平凡人。", "speaker": "大人", "tone": "宠溺", "sound": []}, {"ts": "00:04:03", "text": "洗笑眼睛。", "speaker": "大人", "tone": "宠溺", "sound": []}, {"ts": "00:04:03", "text": "他说。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:04:03", "text": "这真是我想要的。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:04:03", "text": "你说这只羊需要很多草吗？", "speaker": "大人", "tone": "询问", "sound": []}, {"ts": "00:04:03", "text": "为什么？", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:04:03", "text": "问这个呢？", "speaker": "大人", "tone": "询问", "sound": []}, {"ts": "00:04:03", "text": "因为我那里非常的小。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:04:03", "text": "我给你画的是一只很小的羊。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:04:03", "text": "地方小也能够喂养他的。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:04:03", "text": "他把脑袋靠近这张画。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:04:03", "text": "并不像你说的那么小。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:04:03", "text": "脚。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:04:03", "text": "他睡著了。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:04:03", "text": "就这样。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:04:03", "text": "我认识了小王子。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:04:03", "text": "晚安。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:04:03", "text": "宝贝。", "speaker": "大人", "tone": "撒娇", "sound": []}, {"ts": "00:04:03", "text": "开场贝贝。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:04:03", "text": "睡觉家了。", "speaker": "大人", "tone": "平静", "sound": []}], "scene": "朗读类（文学有声书）。叙述者回忆飞机坠毁撒哈拉沙漠、孤身维羞的处境，以及一个奇怪的小孩（小王子）出现，反复要求他画一只羊。经过多次尝试与拒绝，叙述者最终画了一个盒子说羊在里面，小王子满意。基调奇遇、童趣，主题为相遇与纯真。无亲密或惩罚情节。", "behaviors": [{"desc": "叙述者回忆飞机坠毁沙漠、孤身面对维修与孤独"}, {"desc": "小王子出现，要求叙述者为他画一只羊"}, {"desc": "叙述者多次尝试画羊，小王子逐一拒绝并说明原因"}, {"desc": "叙述者画盒子说羊在里面，小王子满意；以晚安宝贝收尾"}], "tone_summary": "（自动）大人视角独白，语气以平静、宠溺、命令为主，题材偏现代情侣。", "genre_tags": ["现代情侣"], "genre_main": "现代情侣", "emotion_arc": "（自动）平静", "intensity": "中", "listener_role": "（自动）被大人倾诉/照顾/管教的一方（你）", "signature_elements": [], "sensitive": false, "tier": "auto", "story": [{"type": "narr", "text": "我就这样孤独地生活着，没有一个能真正谈得来的人。一直到六年前，在撒哈拉沙漠上发生那次事故：我的发动机里有个东西损坏了。由于我既没有带机械师，也没有带旅客，我就试图独自完成这个困难的维修工作。这对我来说，是个生死攸关的问题。"}, {"type": "narr", "text": "我随身带的水只够喝一个星期。第一天晚上，我就睡在这远离人间烟火的大沙漠上。我比大海中附在小木牌上的遇难者还要孤独很多。而第二天拂晓，当一个奇怪的小声音叫醒我的时候，你们可以想见我当时多么吃惊。"}, {"type": "line", "speaker": "小王子", "text": "请你给我画一只山羊好吗？"}, {"type": "line", "speaker": "小王子", "text": "给我画一只羊。"}, {"type": "narr", "text": "我像是受到了惊雷的轰击一样，一下子就站了起来。我使劲地揉了揉眼睛，仔细地看了看。我看见一个十分奇怪的小家伙，严肃地朝我凝望着。"}, {"type": "narr", "text": "这是后来我给他画出来的最好的画像。可是我的话，当然要比他本人的模样逊色很多。这不是我的过错——六岁的时候，大人们使我对画画儿的生涯失去了勇气，除了画过开着肚皮和闭着肚皮的蟒蛇，后来我再没有学过画。"}, {"type": "narr", "text": "我惊奇地瞪大眼看着这突然出现的小家伙。你们不要忘记，我当时是处在远离人间千里之外的地方。而这个小家伙给我的印象是：他既不像迷了路的样子，也没有半点疲乏、饥渴、惧怕的神情。他似乎不像是一个迷失在大沙漠中的孩子。"}, {"type": "narr", "text": "当我在惊讶之中终于能说出话来的时候，对他说："}, {"type": "line", "speaker": "我", "text": "你在这儿干什么？"}, {"type": "narr", "text": "可是他却不慌不忙的，好像有一件重要的事情一般，对我重复说道："}, {"type": "line", "speaker": "小王子", "text": "请你给我画一只山羊。"}, {"type": "narr", "text": "当一种神秘的东西把你震慑住的时候，你是不敢不听从它的支配的。在这杳无人烟的沙漠上，面临死亡危险的情况下，尽管这样的举动让我觉得十分荒诞，但我还是掏出了纸和笔。"}, {"type": "narr", "text": "可是我记起，我只学过地理、历史、算术和语法，就有点不太开心地对小家伙说我不会画画。"}, {"type": "line", "speaker": "小王子", "text": "没有关系。给我画一只羊吧。"}, {"type": "narr", "text": "因为我从来没有画过羊，我就给他画了我仅仅会画的两幅画中的一幅——那幅闭着肚皮的蟒蛇。"}, {"type": "line", "speaker": "小王子", "text": "不，不，不要蟒蛇。他肚子里还有一头大象。"}, {"type": "narr", "text": "我听了他的话，简直目瞪口呆。他接着说："}, {"type": "line", "speaker": "小王子", "text": "蟒蛇这东西太危险了。大象又太占地方。我住的地方非常小。我需要一只羊。给我画一只羊吧。"}, {"type": "narr", "text": "于是我就给他画了。他专心地看着，最后又说："}, {"type": "line", "speaker": "小王子", "text": "我不要。这只羊已经病得很重了。给我重新画一只。"}, {"type": "narr", "text": "我又画了起来。我的这位朋友天真可爱地笑了，并且客气地拒绝道："}, {"type": "line", "speaker": "小王子", "text": "你看，你画的不是小羊，是头公羊，还有犄角呢。"}, {"type": "narr", "text": "于是我又重新画了一张。这幅画和前几幅一样，也被拒绝了。"}, {"type": "line", "speaker": "小王子", "text": "这只太老了。我想要一只能活得长的羊。"}, {"type": "narr", "text": "我不耐烦了，因为我急于要拆修发动机。于是我就草草地画了这张画，对他说道："}, {"type": "line", "speaker": "我", "text": "这是一个盒子。你要的羊就在里面。"}, {"type": "narr", "text": "当时我十分惊奇地看到，我的这位小评判员笑逐颜开。他说："}, {"type": "line", "speaker": "小王子", "text": "这真是我想要的。你说这只羊需要很多草吗？"}, {"type": "narr", "text": "我问他为什么问这个。"}, {"type": "line", "speaker": "小王子", "text": "因为我那里非常的小。"}, {"type": "line", "speaker": "我", "text": "我给你画的是一只很小的羊，地方小也能够喂养它的。"}, {"type": "narr", "text": "他把脑袋靠近这张画。并不像你说的那么小。瞧，它睡着了。就这样，我认识了小王子。"}, {"type": "narr", "text": "晚安，宝贝。"}]}, {"no": 128, "id": "pBQrIcZeMo8", "title": "【Lの女性向音声】小王子 五", "title_zh": "小王子 五", "duration": "00:05:03", "link": "https://www.youtube.com/watch?v=pBQrIcZeMo8", "enriched": true, "lines": [{"ts": "00:00:00", "text": "每天我都了解到一些关于小王子的星球、他的出走和旅行等事情，这些都是偶然从各种反应中慢慢得到的。就这样，第二天我就了解到关于猴面包树的悲剧。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "这一次又是一件很了不起的事。突然小王子好像非常担心地问我：羊吃小灌木，这是真的吗？", "speaker": "他", "tone": "询问", "sound": []}, {"ts": "00:00:00", "text": "是的，是真的。我真高兴。我不明白羊吃小灌木这件事情为什么如此重要，可小王子又说了：因为它们也是猴面包树。我对小王子说：猴面包树可不是小灌木，而是像教堂那么大的大树，即使是带回一群大象，也顶不了一棵猴面包树。", "speaker": "他", "tone": "责备", "sound": []}, {"ts": "00:00:00", "text": "一群大象这种想法让小王子发笑：那得把大象一只一只叠起来。他很坚决地说：猴面包树在长大之前，开始也是小小的。不错，可是为什么你想让你的羊去吃小猴面包树呢？", "speaker": "他", "tone": "询问", "sound": []}, {"ts": "00:00:00", "text": "他会回答我：这还用说！似乎这是不言而喻的。可是我自己要花很大的心思才能弄懂这个问题。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "原来小王子的星球就像其他的所有星球一样，有好草和坏草，因此也就有好的草籽和坏的草籽。可是草籽是看不见的，它们沉睡在泥土里，直到其中一粒突然想要苏醒过来，伸个懒腰，先朝着太阳，长出一个可爱的小嫩苗。", "speaker": "他", "tone": "命令", "sound": []}, {"ts": "00:00:00", "text": "如果是小萝卜或是玫瑰的嫩苗，就让它自由地生长；如果是一颗坏苗，一旦被辨认出来，就应该马上把它拔掉。因为在小王子的星球上，有些非常可怕的种子，这就是猴面包树的种子。", "speaker": "他", "tone": "温柔", "sound": []}, {"ts": "00:00:00", "text": "在那里的泥土里，这种种子多成灾。而一颗猴面包树的树苗，假如你拔得太迟，就再也无法把它清除掉，它就会盘踞整个星球。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "它的树根能把星球钻透。如果星球很小，而猴面包树很多，它就把整个星球搞得支离破碎。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "这是个纪律问题。小王子后来向我解释的：当你早上梳洗完毕以后，必须仔细给星球梳洗，必须规定自己按时去拔掉猴面包树的树苗。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "这种树苗小的时候，和玫瑰苗差不多，一旦可以把它们区分开的时候就要把它拔掉。这是一件非常乏味的工作，但是很容易。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "有一天他劝我用心画一幅漂亮的图画，好让我家乡的孩子们对这件事有一个深刻的印象。他还对我说：", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "如果将来有一天他们外出旅行，这对他们是很有用的。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "有时候，人们把自己的工作推到以后去做，并没有什么妨碍。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "但要遇到把猴面包树苗这样的事儿，那就非造成大灾难不可喽。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "我遇到过一个星球，上面住着一个懒家伙，它放过了三颗树苗。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "于是根据小王子的说明把这个星球画了下来。我从来不大愿意以道学家的口吻来说话，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "可是猴面包树的悲剧，大家都不太了解。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "对迷失在小行星上的人来说，危险性是非常大的。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "因此这回我冒然打破了我这个不喜欢教训人的惯例。", "speaker": "他", "tone": "宠溺", "sound": []}, {"ts": "00:00:00", "text": "我说：孩子们，要当心那些猴面包树呀！", "speaker": "他", "tone": "撒娇", "sound": []}, {"ts": "00:00:00", "text": "为了叫我的朋友们警惕这种危险，他们同我一样，长期以来和这种危险接触，却没有意识到它的危险性。", "speaker": "他", "tone": "宠溺", "sound": []}, {"ts": "00:00:00", "text": "我花了很大的功夫，画了这幅画。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "我提出的这个教训意义是很大的，花点功夫是值得的。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "你们也许要问，为什么这本书中，别的话都没有这幅画这么壮观呢？", "speaker": "他", "tone": "询问", "sound": []}, {"ts": "00:00:00", "text": "回答很简单：别的话我也曾经是画得很好，却没成功。", "speaker": "他", "tone": "命令", "sound": []}, {"ts": "00:00:00", "text": "而当我画猴面包树时，有一种急切的心情，激励着我。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "晚安。", "speaker": "他", "tone": "平静", "sound": []}], "scene": "朗读类（文学有声书）。叙述者转述从小王子处了解的猴面包树危害与拔除纪律：星球上的坏种子须及早拔除，否则会撑裂整个星球。叙述者据此作画并借机告诫读者警惕此类危险。基调说理、劝诫，主题为纪律与责人意识。无亲密或惩罚情节。", "behaviors": [{"desc": "叙述者从小王子处了解猴面包树的危害与拔除纪律"}, {"desc": "小王子解释每日起床后须仔细拔除幼苗的纪律要求"}, {"desc": "叙述者据此作画并告诫读者警惕猴面包树；以晚安收尾"}], "tone_summary": "（自动）他视角独白，语气以平静、询问、命令为主，题材偏职场。", "genre_tags": ["职场"], "genre_main": "职场", "emotion_arc": "（自动）平静", "intensity": "中", "listener_role": "（自动）被他倾诉/照顾/管教的一方（你）", "signature_elements": [], "sensitive": false, "tier": "auto", "story": [{"type": "narr", "text": "夜色安静，他的声音继续着那个遥远星球的故事，像在轻轻擦拭一段记忆。他翻过一页，慢慢念下去。"}, {"type": "line", "speaker": "他", "text": "每天我都了解到一些关于小王子的星球、他的出走和旅行等事情，这些都是偶然从各种反应中慢慢得到的。就这样，第二天我就了解到关于猴面包树的悲剧。这一次又是一件很了不起的事。突然小王子好像非常担心地问我：羊吃小灌木，这是真的吗？是的，是真的。我真高兴。我不明白羊吃小灌木这件事情为什么如此重要，可小王子又说了：因为它们也是猴面包树。我对小王子说：猴面包树可不是小灌木，而是像教堂那么大的大树，即使是带回一群大象，也顶不了一棵猴面包树。"}, {"type": "narr", "text": "他念到小王子天真的问题，声音里带着一点温和的笑意，继续讲下去。"}, {"type": "line", "speaker": "他", "text": "一群大象这种想法让小王子发笑：那得把大象一只一只叠起来。他很坚决地说：猴面包树在长大之前，开始也是小小的。不错，可是为什么你想让你的羊去吃小猴面包树呢？他会回答我：这还用说！似乎这是不言而喻的。可是我自己要花很大的心思才能弄懂这个问题。原来小王子的星球就像其他的所有星球一样，有好草和坏草，因此也就有好的草籽和坏的草籽。可是草籽是看不见的，它们沉睡在泥土里，直到其中一粒突然想要苏醒过来，伸个懒腰，先朝着太阳，长出一个可爱的小嫩苗。"}, {"type": "narr", "text": "他停了停，声音低下来，像在说一个关于成长的比喻。"}, {"type": "line", "speaker": "他", "text": "如果是小萝卜或是玫瑰的嫩苗，就让它自由地生长；如果是一颗坏苗，一旦被辨认出来，就应该马上把它拔掉。因为在小王子的星球上，有些非常可怕的种子，这就是猴面包树的种子。在那里的泥土里，这种种子多成灾。而一颗猴面包树的树苗，假如你拔得太迟，就再也无法把它清除掉，它就会盘踞整个星球。它的树根能把星球钻透。如果星球很小，而猴面包树很多，它就把整个星球搞得支离破碎。"}, {"type": "narr", "text": "他合上这一页前，声音带着故事特有的郑重。"}, {"type": "line", "speaker": "他", "text": "这是个纪律问题。小王子后来向我解释的：当你早上梳洗完毕以后，必须仔细给星球梳洗，必须规定自己按时去拔掉猴面包树的树苗。这种树苗小的时候，和玫瑰苗差不多，一旦可以把它们区分开的时候就要把它拔掉。这是一件非常乏味的工作，但是很容易。有一天他劝我用心画一幅漂亮的图画，好让我家乡的孩子们对这件事有一个深刻的印象。他还对我说：如果将来有一天他们外出旅行，这对他们是很有用的。有时候，人们把自己的工作推到以后去做，并没有什么妨碍。但要遇到把猴面包树苗这样的事儿，那就非造成大灾难不可喽。"}, {"type": "narr", "text": "他念到这里，语气带上了一点告诫的认真。"}, {"type": "line", "speaker": "他", "text": "我遇到过一个星球，上面住着一个懒家伙，它放过了三颗树苗。于是根据小王子的说明把这个星球画了下来。我从来不大愿意以道学家的口吻来说话，可是猴面包树的悲剧，大家都不太了解。对迷失在小行星上的人来说，危险性是非常大的。因此这回我冒然打破了我这个不喜欢教训人的惯例。我说：孩子们，要当心那些猴面包树呀！为了叫我的朋友们警惕这种危险，他们同我一样，长期以来和这种危险接触，却没有意识到它的危险性。我花了很大的功夫，画了这幅画。我提出的这个教训意义是很大的，花点功夫是值得的。你们也许要问，为什么这本书中，别的话都没有这幅画这么壮观呢？回答很简单：别的话我也曾经是画得很好，却没成功。而当我画猴面包树时，有一种急切的心情，激励着我。"}, {"type": "narr", "text": "他合上书，轻轻说了句晚安。夜很深，那个关于猴面包树的告诫，却像一颗种子，落进了听故事的人心里。有些坏习惯，就像猴面包树，要在它还小的时候，就把它拔掉。"}]}, {"no": 129, "id": "dgR0YsXrN2M", "title": "【Lの女性向音声】小王子 八", "title_zh": "小王子 八", "duration": "00:05:55", "link": "https://www.youtube.com/watch?v=dgR0YsXrN2M", "enriched": true, "lines": [{"ts": "00:00:00", "text": "很快，我就进一步了解了这朵花儿。在小王子的星球上，过去一直都生长着一些只有一层花瓣的很简单的花儿，这些花非常小，一点儿也不占地盘，从来也不去打扰任何人。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "它们早晨在草丛里开放，晚上就凋谢了。不知从哪里来了一颗种子，忽然有一天，这颗种子发了芽。小王子特别仔细地监视着这颗与众不同的小苗，这说不定是一种新的猴面包树。", "speaker": "他", "tone": "命令", "sound": []}, {"ts": "00:00:00", "text": "但是这小苗不久就不再长了，而且开始孕育着一个花朵。看到在这棵苗上长出一个很大很大的花蕾，小王子感觉到，感觉到从这个花苞中一定会出现一个奇迹。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "然而这朵花藏在那绿茵茵的房间里，用了很长的时间来打扮自己。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "它精心选择着它将来的颜色，慢慢腾腾地装饰着，一片片地搭配着它的花瓣。", "speaker": "他", "tone": "温柔", "sound": []}, {"ts": "00:00:00", "text": "它不愿像虞美人那样一出现就满脸的皱纹，它要让自己带着光艳夺目的丽姿来到世界。没错，它是非常爱美的。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "它用好些好些日子，天仙般地梳妆打扮，然后在一天早晨，恰好在太阳升起的时候，它开放了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "它已经精细地做了那么长的准备工作，却打着哈欠说道。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "我刚刚睡醒，真对不起，瞧我的头发还是乱蓬蓬的。", "speaker": "他", "tone": "宠溺", "sound": []}, {"ts": "00:00:00", "text": "小王子再也控制不住自己爱慕的心情：你是多么美呀！", "speaker": "他", "tone": "撒娇", "sound": []}, {"ts": "00:00:00", "text": "花儿怡然自得地说道：是吧，我是与太阳同时出生的。", "speaker": "他", "tone": "责备", "sound": []}, {"ts": "00:00:00", "text": "小王子看出了这朵花不太谦虚，可是它确实动人心魄。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "它随后又说道：现在是该吃早点的时候了吧。", "speaker": "他", "tone": "责备", "sound": []}, {"ts": "00:00:00", "text": "请你殷勤地也想着给我准备一点。", "speaker": "他", "tone": "命令", "sound": []}, {"ts": "00:00:00", "text": "小王子有些不好意思，于是拿着喷壶，打了一壶清凉的凉水。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "浇灌着花儿。于是就这样，这朵花儿就用它那有点敏感多疑的虚荣心，折磨着小王子。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "例如有一天，它向小王子讲起它身上长着四根刺。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "老虎，让它张着爪子来吧。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "小王子顶了它一句：在我这个星球上没有老虎。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "而且老虎是不会吃草的。花儿轻声地说道：我并不是草。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "真对不起。我并不怕什么老虎，可我讨厌穿堂风。你没有屏风吗？", "speaker": "他", "tone": "询问", "sound": []}, {"ts": "00:00:00", "text": "小王子思索着：讨厌穿堂风，这对植物来讲真不走运。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "这朵花儿真不大好伺候。晚上你得把我保护好。你这地方太冷了。", "speaker": "他", "tone": "温柔", "sound": []}, {"ts": "00:00:00", "text": "在这儿，住得不好。我原来住的那个地方——但它没有说下去。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "但来的时候是颗种子，它哪里见过什么别的世界。", "speaker": "他", "tone": "命令", "sound": []}, {"ts": "00:00:00", "text": "它让人发现它是在撒一个如此不高明的谎。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "它有点羞愧难当，可咳了两三声。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "它的这一招是要小王子处于有过错的地位。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "它说道：屏风呢？我这就去拿。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "可你刚才说的是——于是花儿放开嗓门咳了几声。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "依然要使小王子后悔自己的过失。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "尽管小王子本来诚心诚意地喜欢这朵花。", "speaker": "他", "tone": "宠溺", "sound": []}, {"ts": "00:00:00", "text": "可是这一来，却使他马上对它产生了怀疑。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "小王子对一些无关紧要的话，看得太认真。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "结果是自己很苦恼。", "speaker": "他", "tone": "温柔", "sound": []}, {"ts": "00:00:00", "text": "有一天他告诉我说。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "我该不该听信它的话？绝不该听信那些花儿的话。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "看看它，闻闻它，就得了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "我那朵花使我的星球芳香四溢。", "speaker": "他", "tone": "宠溺", "sound": []}, {"ts": "00:00:00", "text": "可我不会享受它。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "关于老虎爪子的事吧。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "本该使我产生同情。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "却反而使我烦恼。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "还有点恼火。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "他还告诉我说。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "那时候我什么也不懂。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "我应该根据它的行为，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "而不是根据它的话来判断它。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "它使我的生活，芬芳多彩。", "speaker": "他", "tone": "宠溺", "sound": []}, {"ts": "00:00:00", "text": "我真不该离开它跑出来。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "我本应该猜出来，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "在它那可怜的小花招后面，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "藏着温情。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "花是懂得自相矛盾的。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "我当时太年轻，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "还不懂得爱它。", "speaker": "他", "tone": "平静", "sound": []}], "scene": "朗读类（文学有声书）。叙述者回忆星球上那朵独一无二的花的诞生与精心打扮，以及她以虚荣与娇气考验小王子（要求清晨饮水、怕穿堂风、要庇护）。小王子最终反思自己因轻信话语而苦恼，懊悔离开与不懂爱。基调细腻感伤，主题为爱与误解。无亲密或惩罚情节。", "behaviors": [{"desc": "叙述者回忆那朵独一无二的花的诞生与精心打扮"}, {"desc": "花以虚荣与娇气考验小王子，要求饮水与庇护"}, {"desc": "小王子反思自己因轻信话语而苦恼，懊悔离开与不懂爱"}], "tone_summary": "（自动）他视角独白，语气以平静、宠溺、命令为主，题材偏现代情侣。", "genre_tags": ["现代情侣"], "genre_main": "现代情侣", "emotion_arc": "（自动）平静", "intensity": "中", "listener_role": "（自动）被他倾诉/照顾/管教的一方（你）", "signature_elements": [], "sensitive": false, "tier": "auto", "story": [{"type": "narr", "text": "台灯的光落在书页上，他的声音低沉而舒缓，像是在讲一个很旧很旧的故事。他翻过一页，慢慢念下去。"}, {"type": "line", "speaker": "他", "text": "很快，我就进一步了解了这朵花儿。在小王子的星球上，过去一直都生长着一些只有一层花瓣的很简单的花儿，这些花非常小，一点儿也不占地盘，从来也不去打扰任何人。"}, {"type": "narr", "text": "他停了停，目光落在那行字上，声音带着一点讲故事时才有的温柔。"}, {"type": "line", "speaker": "他", "text": "它们早晨在草丛里开放，晚上就凋谢了。不知从哪里来了一颗种子，忽然有一天，这颗种子发了芽。小王子特别仔细地监视着这颗与众不同的小苗，这说不定是一种新的猴面包树。"}, {"type": "narr", "text": "故事在夜色里缓缓流淌。他的声音放轻了些，像怕惊动什么。"}, {"type": "line", "speaker": "他", "text": "但是这小苗不久就不再长了，而且开始孕育着一个花朵。看到在这棵苗上长出一个很大很大的花蕾，小王子感觉到，感觉到从这个花苞中一定会出现一个奇迹。"}, {"type": "line", "speaker": "他", "text": "然而这朵花藏在那绿茵茵的房间里，用了很长的时间来打扮自己。它精心选择着它将来的颜色，慢慢腾腾地装饰着，一片片地搭配着它的花瓣。"}, {"type": "narr", "text": "他念到这里，语气带着一点笑意，像在说一个爱美的小姑娘。"}, {"type": "line", "speaker": "他", "text": "它不愿像虞美人那样一出现就满脸的皱纹，它要让自己带着光艳夺目的丽姿来到世界。没错，它是非常爱美的。它用好些好些日子，天仙般地梳妆打扮，然后在一天早晨，恰好在太阳升起的时候，它开放了。"}, {"type": "narr", "text": "他顿了顿，声音里带着故事特有的温度。"}, {"type": "line", "speaker": "他", "text": "它已经精细地做了那么长的准备工作，却打着哈欠说道。我刚刚睡醒，真对不起，瞧我的头发还是乱蓬蓬的。小王子再也控制不住自己爱慕的心情：你是多么美呀！"}, {"type": "line", "speaker": "他", "text": "花儿怡然自得地说道：是吧，我是与太阳同时出生的。小王子看出了这朵花不太谦虚，可是它确实动人心魄。它随后又说道：现在是该吃早点的时候了吧。请你殷勤地也想着给我准备一点。"}, {"type": "narr", "text": "他念着，声音里带着一点会心的笑意。夜很深，故事却还在继续。"}, {"type": "line", "speaker": "他", "text": "小王子有些不好意思，于是拿着喷壶，打了一壶清凉的凉水。浇灌着花儿。于是就这样，这朵花儿就用它那有点敏感多疑的虚荣心，折磨着小王子。例如有一天，它向小王子讲起它身上长着四根刺。老虎，让它张着爪子来吧。"}, {"type": "line", "speaker": "他", "text": "小王子顶了它一句：在我这个星球上没有老虎。而且老虎是不会吃草的。花儿轻声地说道：我并不是草。真对不起。我并不怕什么老虎，可我讨厌穿堂风。你没有屏风吗？"}, {"type": "narr", "text": "他念到花儿撒娇耍赖的段落，语气里带着一点无奈的笑意，像在说一个任性的孩子。"}, {"type": "line", "speaker": "他", "text": "小王子思索着：讨厌穿堂风，这对植物来讲真不走运。这朵花儿真不大好伺候。晚上你得把我保护好。你这地方太冷了。在这儿，住得不好。我原来住的那个地方——但它没有说下去。"}, {"type": "line", "speaker": "他", "text": "但来的时候是颗种子，它哪里见过什么别的世界。它让人发现它是在撒一个如此不高明的谎。它有点羞愧难当，可咳了两三声。它的这一招是要小王子处于有过错的地位。它说道：屏风呢？我这就去拿。"}, {"type": "narr", "text": "他停了停，声音低下去，带着故事才有的沉静。"}, {"type": "line", "speaker": "他", "text": "可你刚才说的是——于是花儿放开嗓门咳了几声。依然要使小王子后悔自己的过失。尽管小王子本来诚心诚意地喜欢这朵花。可是这一来，却使他马上对它产生了怀疑。"}, {"type": "line", "speaker": "他", "text": "小王子对一些无关紧要的话，看得太认真。结果是自己很苦恼。有一天他告诉我说。我该不该听信它的话？绝不该听信那些花儿的话。看看它，闻闻它，就得了。"}, {"type": "narr", "text": "他念到这段自白，声音里带着一点怅然。夜风从窗外轻轻吹进来，书页微微晃动。"}, {"type": "line", "speaker": "他", "text": "我那朵花使我的星球芳香四溢。可我不会享受它。关于老虎爪子的事吧。本该使我产生同情。却反而使我烦恼。还有点恼火。"}, {"type": "narr", "text": "他合上这一章前，声音放得很轻，像在念一句很久以后才会懂得的话。"}, {"type": "line", "speaker": "他", "text": "他还告诉我说。那时候我什么也不懂。我应该根据它的行为，而不是根据它的话来判断它。它使我的生活，芬芳多彩。我真不该离开它跑出来。"}, {"type": "line", "speaker": "他", "text": "我本应该猜出来，在它那可怜的小花招后面，藏着温情。花是懂得自相矛盾的。我当时太年轻，还不懂得爱它。"}, {"type": "narr", "text": "他念完最后一句，轻轻合上书。屋里很安静，只剩下书页合拢的声响。那句话在夜色里停了很久——我当时太年轻，还不懂得爱它。有些道理，要等很久以后，才会真正听懂。"}]}, {"no": 130, "id": "NefTbDFR4gg", "title": "【Lの女性向音声】小王子 六", "title_zh": "小王子 六", "duration": "00:01:48", "link": "https://www.youtube.com/watch?v=NefTbDFR4gg", "enriched": true, "lines": [{"ts": "00:00:00", "text": "小王子就是这样，我逐渐懂得了你那忧郁的生活。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "过去相当长的时间里，你唯一的乐趣就是观赏夕阳西下的温柔景色。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "这个新的细节是我在第四天早晨才知道的。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "你当时对我说：我喜欢看日落，我们去看一回日落吧。", "speaker": "他", "tone": "宠溺", "sound": []}, {"ts": "00:00:00", "text": "可是，日落得等着。等什么？等太阳下山。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "开始你总是显得很惊喜的样子。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "最后你笑自己糊涂。", "speaker": "他", "tone": "宠溺", "sound": []}, {"ts": "00:00:00", "text": "你对我说：我还以为是在我家乡呢！", "speaker": "他", "tone": "询问", "sound": []}, {"ts": "00:00:00", "text": "确实大家都知道，在美国是正午时分，在法国是夕阳西下。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "只要在一分钟内看到法国，就可以看到日落。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "可惜法国是那么遥远。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "而在你那样的小行星上，你只要把椅子挪动几步就行了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "这样，就可以随时看到你想看的夕阳余晖。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "有一天，我见过四十三次日落。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "过了一会儿，你又说：你知道，当人们感到非常苦闷时，", "speaker": "他", "tone": "温柔", "sound": []}, {"ts": "00:00:00", "text": "总是喜欢日落。", "speaker": "他", "tone": "宠溺", "sound": []}, {"ts": "00:00:00", "text": "一天四十三次，你怎么会这么苦闷。", "speaker": "他", "tone": "温柔", "sound": []}, {"ts": "00:00:00", "text": "小王子没有回答。晚安了。", "speaker": "他", "tone": "平静", "sound": []}], "scene": "朗读类（文学有声书）。小王子向叙述者表达对看日落的膝盖，并说起自己曾在一天里看了四十三次日落，暗含愁绪；叙述者询问缘由未得回应。基调安静忧郁，主题为孤独与情绪。无亲密或惩罚情节。", "behaviors": [{"desc": "小王子表达喜欢看日落，与叙述者约定一起看"}, {"desc": "小王子说起一天看过四十三次日落，暗含苦闷"}, {"desc": "叙述者询问缘由未得回应；以晚安收尾"}], "tone_summary": "（自动）他视角独白，语气以平静、宠溺、温柔为主，题材偏现代情侣。", "genre_tags": ["现代情侣"], "genre_main": "现代情侣", "emotion_arc": "（自动）平静", "intensity": "中", "listener_role": "（自动）被他倾诉/照顾/管教的一方（你）", "signature_elements": [], "sensitive": false, "tier": "auto", "story": [{"type": "narr", "text": "我渐渐懂得了小王子那忧郁的生活。过去很长一段时间里，他唯一的乐趣，就是观赏夕阳西下的温柔景色。这个细节，是我在第四天早晨才知道的。"}, {"type": "line", "speaker": "他", "text": "我喜欢看日落，我们去看一回日落吧。"}, {"type": "narr", "text": "可是日落得等着——等什么？等太阳下山。起初他总是显得很惊喜的样子，最后又笑自己糊涂。"}, {"type": "line", "speaker": "他", "text": "我还以为是在我家乡呢！"}, {"type": "narr", "text": "确实，大家都知道：在美国是正午时分，在法国是夕阳西下。只要在一分钟内赶到法国，就能看到日落。可惜法国是那么遥远。而在小王子那样的小行星上，他只要把椅子挪动几步，就能随时看到想看的夕阳余晖。"}, {"type": "line", "speaker": "他", "text": "有一天，我见过四十三次日落。"}, {"type": "narr", "text": "过了一会儿，他又说，当人们感到非常苦闷时，总是喜欢日落。"}, {"type": "line", "speaker": "他", "text": "一天四十三次，你怎么会这么苦闷。"}, {"type": "narr", "text": "小王子没有回答。晚安了。"}]}, {"no": 131, "id": "LcgntMSyQ1w", "title": "【Lの女性向音声】小王子 十", "title_zh": "小王子 十", "duration": "00:09:54", "link": "https://www.youtube.com/watch?v=LcgntMSyQ1w", "enriched": true, "lines": [{"ts": "00:00:00", "text": "在附近的宇宙中，还有三二五，三二六，三二七，三二八，三二九，等即刻小星星。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:00:07", "text": "它就开始访问这几个星球，现在那里找点事感，并且学习学习。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:00:14", "text": "第一个星球让着着一个国王，国王穿着用紫红色和白底黑花的毛皮做成的大礼服。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:00:21", "text": "坐在一个很简单，有很悲严的宝座上。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:00:28", "text": "他看到小王子是喊了起来，来了一个陈明。", "speaker": "陛下", "tone": "命令", "sound": []}, {"ts": "00:00:35", "text": "小王子思量着，他从来没有见过我，怎么会认识我呢？", "speaker": "陛下", "tone": "询问", "sound": []}, {"ts": "00:00:42", "text": "他哪里知道，在那些国王的眼里，世界非常简单，所有人都是陈明。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:00:49", "text": "国王十分骄傲，因为他终于成了某个人的国王。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:00:56", "text": "他对小王子说，靠近一些，还让我好好看看你。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:01:03", "text": "小王子看看四周，想找个地方坐下来。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:01:11", "text": "可是整个星球，被国王华历的白底黑花皮炮占满了。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:01:18", "text": "他只要站在那里，但是因为皮炼了，他打起哈浅。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:01:25", "text": "均忙对他说，在一个国王面前打哈浅，是违反理结的。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:01:32", "text": "我禁止你打哈浅，小王子修归的说道。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:01:39", "text": "我实在是忍不住，我长多把事来到这里，还没有睡觉呢？", "speaker": "陛下", "tone": "询问", "sound": []}, {"ts": "00:01:46", "text": "国王说，好吧，我面临你打哈浅。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:01:53", "text": "好新年来，我没有看见过任何人打哈浅，对我来说。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:02:00", "text": "打哈浅倒是心奇的事儿，来吧，再打一个，这是命令。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:02:07", "text": "知道让我一点紧张了，我打不住哈浅来了，小王子红着你也说。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:02:15", "text": "国王回答到，那么面临你火花打哈浅，火花。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:02:18", "text": "他独动到囊的，显受点脑怒。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:02:22", "text": "因为国王所要求的，主要是保持他的危言受到尊敬。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:02:26", "text": "他不能容忍不停他的面临，他是一位绝对的群主。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:02:30", "text": "可是他却很善良，他下的命令都是有理智的。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:02:34", "text": "他常常说，如果我叫一位将军变成一只海鸟。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:02:37", "text": "而是为将军不服从我的命令。", "speaker": "陛下", "tone": "宠溺", "sound": []}, {"ts": "00:02:41", "text": "那么这就不是将军的错，是我的过错了。", "speaker": "陛下", "tone": "宠溺", "sound": []}, {"ts": "00:02:45", "text": "可是小王子，面前的试谈道，我可以坐下吗？", "speaker": "陛下", "tone": "询问", "sound": []}, {"ts": "00:02:49", "text": "我面临你坐下，国王一边回答，一边装重的。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:02:53", "text": "把皮炮大筋挪动了一下。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:02:57", "text": "小王子感到很奇怪，这么小的星球。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:03:00", "text": "国王对他进行什么同志呢？", "speaker": "陛下", "tone": "询问", "sound": []}, {"ts": "00:03:04", "text": "他对国王说，陛下请原谅。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:03:08", "text": "我想问你，国王极王强着说道，我面临你问我。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:03:12", "text": "陛下，你同志什么呢？", "speaker": "陛下", "tone": "询问", "sound": []}, {"ts": "00:03:16", "text": "国王非常简单明了地说，我同志一切，一切。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:03:19", "text": "国王亲亲的用手指他的行星和其他的行星。", "speaker": "陛下", "tone": "撒娇", "sound": []}, {"ts": "00:03:23", "text": "以及所有的行星。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:03:27", "text": "小王子说，同志这一切。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:03:31", "text": "你同志这一切，原来他不仅仅是一个绝对的军主。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:03:35", "text": "而是整个宇宙的军主。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:03:39", "text": "那么，星星都服从你吗？", "speaker": "陛下", "tone": "询问", "sound": []}, {"ts": "00:03:42", "text": "那是当然。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:03:46", "text": "国王对他说，他们立刻就得服从。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:03:50", "text": "我是不允许无纪律的。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:03:54", "text": "这样的权力是小王子经谈不一。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:03:58", "text": "如果掌握了这样的权力。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:04:01", "text": "那么他一天就不只是看到四十三次日落了。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:04:05", "text": "甚至可以看到七十二次，甚至一百次。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:04:09", "text": "或是两百次，也不必能动椅子了。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:04:13", "text": "由于他想起他那被一切的小星球。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:04:17", "text": "心里有点难过。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:04:21", "text": "他大胆提出了一个请求。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:04:24", "text": "我想看日落，请求您。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:04:28", "text": "命令太阳下山吧。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:04:32", "text": "国王说道。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:04:36", "text": "如果命令一个将军像这胡蝶那样。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:04:40", "text": "从这朵花儿飞到那朵花儿。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:04:44", "text": "或者命令他写作一个悲剧剧本。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:04:47", "text": "或者变成一个海鸟。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:04:51", "text": "而如果这位将军既到命令不执行的话。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:04:55", "text": "那么，是他不对。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:04:59", "text": "还是我不对呢？", "speaker": "陛下", "tone": "询问", "sound": []}, {"ts": "00:05:03", "text": "那当然是您的不对。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:05:06", "text": "小王子肯定的会打。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:05:10", "text": "一点也不错。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:05:14", "text": "国王接着说道。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:05:18", "text": "向每个人提出的要求。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:05:22", "text": "应该是他们所能做到的。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:05:26", "text": "全为首先应该尽力在理性的基础上。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:05:29", "text": "如果命令你的老百姓去投海。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:05:33", "text": "他们飞起来革命不和。", "speaker": "陛下", "tone": "命令", "sound": []}, {"ts": "00:05:37", "text": "我的命令是合理的。", "speaker": "陛下", "tone": "宠溺", "sound": []}, {"ts": "00:05:41", "text": "所以我有权要别人服从。", "speaker": "陛下", "tone": "命令", "sound": []}, {"ts": "00:05:45", "text": "那么，提出日落呢？", "speaker": "陛下", "tone": "询问", "sound": []}, {"ts": "00:05:48", "text": "小王子一旦提出一个问题。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:05:52", "text": "他是不会放弃这个问题的。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:05:56", "text": "日落嘛，你会看到的。", "speaker": "陛下", "tone": "撒娇", "sound": []}, {"ts": "00:06:00", "text": "我一定要太阳落山。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:04", "text": "不过按照我的统计科学。", "speaker": "陛下", "tone": "宠溺", "sound": []}, {"ts": "00:06:08", "text": "我得等到条件成熟的时候。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:11", "text": "那这要等到什么时候呢？", "speaker": "陛下", "tone": "询问", "sound": []}, {"ts": "00:06:15", "text": "小王子问到。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:19", "text": "国王在回答之前。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:23", "text": "首先翻译了一本后后的日例。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:27", "text": "嘴里满满的说道。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "日落大雨大雨在今晚。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "七十四十分的时候。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "你将看到我的命令。", "speaker": "陛下", "tone": "宠溺", "sound": []}, {"ts": "00:06:31", "text": "一定会被服从的。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "小王子又打击哈起来。", "speaker": "陛下", "tone": "命令", "sound": []}, {"ts": "00:06:31", "text": "他一旦没有看到日落。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "他有点厌烦了。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "他对国王说。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "我没有必要在在这里了。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "我要走了。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "这被因为刚刚有了一个臣民。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "十分娇资的的国王说道。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "别走，别走。", "speaker": "陛下", "tone": "命令", "sound": []}, {"ts": "00:06:31", "text": "我认命你当大臣。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "什么大臣？", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "司法大臣。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "可是，这没有一个要什么案的人。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "很难说啊！", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "国王说道。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "我这地方有小。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "没有放软架的地方。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "另外，一走落就累。", "speaker": "陛下", "tone": "温柔", "sound": []}, {"ts": "00:06:31", "text": "因此我还没寻试过我的王国呢？", "speaker": "陛下", "tone": "询问", "sound": []}, {"ts": "00:06:31", "text": "不。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "可是我已经看过了。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "小王子说道。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "并探身朝清球的那次。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "看不看。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "那边一个人也没有。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "那么？", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "你就审判你自己啊！", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "这可是最难的了。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "审判自己。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "比审判别人要难得多。", "speaker": "陛下", "tone": "命令", "sound": []}, {"ts": "00:06:31", "text": "你要是能审判好自己。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "你就是一个真正的有才智的人。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "国王回答他。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "我妈。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "随便在什么地方我都可以审渡自己啊！", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "我没有必要非要留在这里。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "国王又说。", "speaker": "陛下", "tone": "责备", "sound": []}, {"ts": "00:06:31-00:06:31", "text": "嗯。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "我想。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "在我的星球上。", "speaker": "陛下", "tone": "宠溺", "sound": []}, {"ts": "00:06:31", "text": "有一只老号子。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "夜里我听见他的声音。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "你可以审判他。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "不时地判除他死刑。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "因此他的生命。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "取决于你的判决。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "可是。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "你要有节制地使用这只号子。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "每次判刑后都要设免他。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "因为只有这么一只号子。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "可是。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "我不愿判死刑。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "我想我还是应该走。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "小王子会打倒。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "不行。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "国王说。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "但是小王子准备完毕之后。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "不像是老君主难过。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "说到。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "如果陛下想要不折不扣的得到服从。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "你可以给我下一个合理的命令。", "speaker": "陛下", "tone": "命令", "sound": []}, {"ts": "00:06:31", "text": "比如说。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "你可以命令我。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "一分钟之内必须离开。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "我认为这个条件是成熟的。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "国王什么也没有回答。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "其说小王子有些犹豫不觉。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "随后。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "探了口气。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "就离开了。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "我判你当我的大使。", "speaker": "陛下", "tone": "宠溺", "sound": []}, {"ts": "00:06:31", "text": "国王从忙的含倒。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "国王显出非常有权威的样子。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "小王子在驴头中自言自语地说。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "这些大人真的很奇怪。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "晚安。", "speaker": "陛下", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "明天见宝贝。", "speaker": "陛下", "tone": "撒娇", "sound": []}], "scene": "朗读类（文学有声书）。小王子拜访一个国王居住的星球。国王以命令口吻与他交谈，主张下达「合理的命令」，小王子趁机请求看日落，国王以「统计科学」推说条件成熟时才可行，并任命小王子为大使。基调寓言式、略带讽刺，主题为权力与理性。无亲密或惩罚情节。", "behaviors": [{"desc": "小王子拜访国王星球，国王以命令口吻与他交谈"}, {"desc": "国王解释其合理命令的治理观念，小王子请求看日落"}, {"desc": "国王以统计科学推迟日落，任命小王子为大使；小王子离开"}], "tone_summary": "（自动）陛下视角独白，语气以平静、询问、命令为主，题材偏古风。", "genre_tags": ["古风", "主仆/调教"], "genre_main": "古风", "emotion_arc": "（自动）平静", "intensity": "中", "listener_role": "（自动）被陛下倾诉/照顾/管教的一方（你）", "signature_elements": [], "sensitive": false, "tier": "auto", "story": [{"type": "narr", "text": "夜色安静，他的声音平稳地继续着那个遥远星球的故事。他翻过一页，慢慢念下去。"}, {"type": "line", "speaker": "陛下", "text": "在附近的宇宙中，还有三二五、三二六、三二七、三二八、三二九这几颗小行星。他开始访问这几个星球，想在那边找点事干，并且学习学习。第一个星球上住着一个国王，国王穿着用紫红色和白底黑花的毛皮做成的大礼服，坐在一个很简单、却又很威严的宝座上。他看到小王子时喊了起来：来了一个臣民。"}, {"type": "narr", "text": "他念到这里，语气带着一点故事特有的笑意，继续念下去。"}, {"type": "line", "speaker": "陛下", "text": "小王子思量着，他从来没有见过我，怎么会认识我呢？他哪里知道，在那些国王的眼里，世界非常简单，所有人都是臣民。国王十分骄傲，因为他终于成了某个人的国王。他对小王子说：靠近一些，让我好好看看你。"}, {"type": "narr", "text": "他的声音带着故事的温度，一字一句，把那颗小行星上的怪国王慢慢描出来。"}, {"type": "line", "speaker": "陛下", "text": "小王子看看四周，想找个地方坐下来。可是整个星球，被国王华丽的皮袍占满了。他只好站在那里，但是因为疲倦了，他打起哈欠。国王连忙对他说：在一个国王面前打哈欠，是违反礼节的，我禁止你打哈欠。小王子羞愧地说道：我实在是忍不住，我长途跋涉来到这里，还没有睡觉呢？"}, {"type": "narr", "text": "他念到国王的古怪逻辑，声音里带着一点忍俊不禁的温和。"}, {"type": "line", "speaker": "陛下", "text": "国王说：好吧，我命令你打哈欠。好些年我没有看见过任何人打哈欠，对我来说，打哈欠倒是新奇的事儿，来吧，再打一个，这是命令。知道让我有点紧张了，我打不出哈欠来了，小王子红着脸说。国王回答道：那么我命令你忽而打哈欠，忽而……他嘟嘟囔囔的，显出有点恼怒。"}, {"type": "narr", "text": "他停了停，声音带着故事特有的郑重，继续念下去。"}, {"type": "line", "speaker": "陛下", "text": "因为国王所要求的，主要是保持他的威严受到尊敬。他不能容忍不听从他的命令，他是一位绝对的君主。可是他却很善良，他下的命令都是有理智的。他常常说：如果我命令一位将军变成一只海鸟，而这位将军不服从我的命令，那么这就不是将军的错，是我的过错了。"}, {"type": "narr", "text": "他念到小王子与国王的对话，语气带着一点会心的笑意。"}, {"type": "line", "speaker": "陛下", "text": "可是小王子怯生生地问道：我可以坐下吗？我命令你坐下，国王一边回答，一边庄重地把皮袍大襟挪动了一下。小王子感到很奇怪：这么小的星球，国王对他进行什么统治呢？他对国王说：陛下请原谅，我想问你——国王急急忙忙说道：我命令你问我。陛下，你统治什么呢？国王非常简单明了地说：我统治一切，一切。国王轻轻地用手指他的行星和其他的行星，以及所有的行星。"}, {"type": "narr", "text": "夜很深，他的声音放轻了些，带着故事特有的味道。"}, {"type": "line", "speaker": "陛下", "text": "小王子说：统治这一切？原来他不仅仅是一个绝对的君主，而是整个宇宙的君主。那么，星星都服从你吗？那是当然，国王对他说，他们立刻就得服从，我是不允许无纪律的。这样的权力是小王子惊叹不已。如果掌握了这样的权力，那么他一天就不只是看到四十三次日落了，甚至可以看到七十二次，甚至一百次，或是两百次，也不必挪动椅子了。由于他想起他那被遗弃的小星球，心里有点难过，他大胆提出了一个请求：我想看日落，请求您命令太阳下山吧。"}, {"type": "narr", "text": "他念到这里，语气带着一点故事才有的哲思，继续往下讲。"}, {"type": "line", "speaker": "陛下", "text": "国王说道：如果我命令一个将军像蝴蝶那样从这朵花儿飞到那朵花儿，或者命令他写作一个悲剧剧本，或者变成一只海鸟，而如果这位将军接到命令不执行的话，那么是他不对，还是我不对呢？那当然是您的不对，小王子肯定地回答。一点也不错，国王接着说：向每个人提出的要求，应该是他们所能做到的。权威首先应该建立在理性的基础上。如果命令你的老百姓去投海，他们非起来革命不可。我的命令是合理的，所以我有权要别人服从。"}, {"type": "narr", "text": "他顿了顿，声音里带着一点会心的笑意，念到小王子追问日落。"}, {"type": "line", "speaker": "陛下", "text": "那么，提出日落呢？小王子一旦提出一个问题，他是不会放弃这个问题的。日落嘛，你会看到的。我一定要太阳落山。不过按照我的统治科学，我得等到条件成熟的时候。那这要等到什么时候呢？小王子问道。国王在回答之前，首先翻阅了一本厚厚的日历，嘴里慢慢地说道：日落大约在今晚七点四十分的时候，你将看到我的命令一定会被服从的。"}, {"type": "narr", "text": "他合上书页前，声音带着故事特有的余味。"}, {"type": "line", "speaker": "陛下", "text": "小王子又打起哈欠来，他一旦没有看到日落，他有点厌烦了。他对国王说：我没有必要再在这里了，我要走了。这被因为刚刚有了一个臣民、十分骄傲的国王说道：别走，别走，我任命你当大臣。什么大臣？司法大臣。可是，这没有一个要审案的人。很难说啊！国王说道：我这地方很小，没有放绞架的地方。另外，一走就累，因此我还没巡视过我的王国呢？不，可是我已经看过了，小王子说道，并探身朝星球的另一侧看了看——那边一个人也没有。那么，你就审判你自己啊！这可是最难的了。审判自己，比审判别人要难得多。你要是能审判好自己，你就是一个真正的有才智的人。"}, {"type": "narr", "text": "他念完最后一段，声音带着一点温和的余韵。夜很静，那些关于国王和审判的道理，在夜色里停了很久。小王子走了，国王喊着任命他当大使——可那些大人，永远看不懂小孩子为什么离开。而他身边的她，已经靠在他肩上，睡着了。"}]}, {"no": 132, "id": "7tb-97jrvTQ", "title": "【Lの女性向音声】小王子 十一", "title_zh": "小王子 十一", "duration": "00:02:17", "link": "https://www.youtube.com/watch?v=7tb-97jrvTQ", "enriched": true, "lines": [{"ts": "00:00:00", "text": "第二个星球上，", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "住着一个爱慕虚荣的人。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "哦哟！", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "一个崇拜我的人来拜访了。", "speaker": "大人", "tone": "宠溺", "sound": []}, {"ts": "00:00:00", "text": "这个爱慕虚荣的人一见到小王子，", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "老远就叫喊起来。", "speaker": "大人", "tone": "命令", "sound": []}, {"ts": "00:00:00", "text": "在那些爱慕虚荣的人眼睛里，", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "别人都成了他们的崇拜者。", "speaker": "大人", "tone": "命令", "sound": []}, {"ts": "00:00:00", "text": "你好。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "你的帽子很奇怪。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "小王子说道。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "这是为了向人们致意用的。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "爱慕虚荣的人回答道。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "当人们向我欢呼的时候，", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "我就用帽子向他们致意。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "唉，", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "可惜没有一个人经过这里。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "小王子不解其意，", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "说道。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "是吗？", "speaker": "大人", "tone": "询问", "sound": []}, {"ts": "00:00:00", "text": "爱慕虚荣的人向小王子提议道。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "你用一只手去拍另一只手。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "小王子就拍起巴掌来。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "这位爱慕虚荣者就谦虚地举起帽子，", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "向小王子致意。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "小王子心想，", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "这比拜访的那位国王有趣。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "于是他又拍起巴掌来。", "speaker": "大人", "tone": "责备", "sound": []}, {"ts": "00:00:00", "text": "爱慕虚荣者又举起帽子向他致意。", "speaker": "大人", "tone": "责备", "sound": []}, {"ts": "00:00:00", "text": "小王子就这样做了五分钟，", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "之后对这种单调的把戏有点厌倦了，", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "说道。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "要是想让你的帽子掉下来，", "speaker": "大人", "tone": "宠溺", "sound": []}, {"ts": "00:00:00", "text": "该怎么做呢？", "speaker": "大人", "tone": "询问", "sound": []}, {"ts": "00:00:00", "text": "可这回爱慕虚荣者听不进他的话，", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "因为凡是爱慕虚荣的人，", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "只听得进赞美的话。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "他问小王子道。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "你真的钦佩我吗？", "speaker": "大人", "tone": "询问", "sound": []}, {"ts": "00:00:00", "text": "呃，", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "钦佩是什么意思？", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "钦佩嘛！", "speaker": "大人", "tone": "撒娇", "sound": []}, {"ts": "00:00:00", "text": "就是承认我是星球上最美的人，", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "服饰最好的人，", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "最富有的人，", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "最聪明的人。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "可您是您星球上唯一的人呀！", "speaker": "大人", "tone": "撒娇", "sound": []}, {"ts": "00:00:00", "text": "让我高兴吧。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "请你还是来钦佩我吧。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "小王子轻轻地耸了耸肩膀，说道。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "我钦佩你。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "可是这有什么能使你这样感兴趣的呢？", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "于是小王子就走开了。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "小王子在路上自言自语地说了一句。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "这些大人啊！", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "肯定是十分古怪的。", "speaker": "大人", "tone": "平静", "sound": []}], "scene": "朗读类（文学有声书）。小王子拜访一个爱慕虚荣的人。对方只听得进赞美，要求小王子拍手致意、承认自己是星球上最美最富有最聪明的人；小王子配合片刻后感到厌倦离去。基调寓言式、轻讽，主题为虚荣。无亲密或惩罚情节。", "behaviors": [{"desc": "小王子拜访爱慕虚荣的人，对方要求被崇拜与赞美"}, {"desc": "小王子拍手致意、配合表演后感到厌倦"}, {"desc": "小王子离去，途中感叹大人们十分古怪"}], "tone_summary": "（自动）大人视角独白，语气以平静、询问、宠溺为主，题材偏现代情侣。", "genre_tags": ["现代情侣"], "genre_main": "现代情侣", "emotion_arc": "（自动）平静", "intensity": "中", "listener_role": "（自动）被大人倾诉/照顾/管教的一方（你）", "signature_elements": [], "sensitive": false, "tier": "auto", "story": [{"type": "narr", "text": "夜色安静，他的声音平稳地继续着那个遥远的故事。他翻过一页，语气里带着讲故事时才有的从容。"}, {"type": "line", "speaker": "大人", "text": "第二个星球上，住着一个爱慕虚荣的人。哦哟！一个崇拜我的人来拜访了。这个爱慕虚荣的人一见到小王子，老远就叫喊起来。在那些爱慕虚荣的人眼睛里，别人都成了他们的崇拜者。"}, {"type": "narr", "text": "他念到这里，声音里带上一丝调侃的笑意，像在说一个夸张的喜剧角色。"}, {"type": "line", "speaker": "大人", "text": "你好。你的帽子很奇怪。小王子说道。这是为了向人们致意用的。爱慕虚荣的人回答道。当人们向我欢呼的时候，我就用帽子向他们致意。唉，可惜没有一个人经过这里。"}, {"type": "narr", "text": "他顿了顿，语气带着故事特有的轻盈，继续念下去。"}, {"type": "line", "speaker": "大人", "text": "小王子不解其意，说道。是吗？爱慕虚荣的人向小王子提议道。你用一只手去拍另一只手。小王子就拍起巴掌来。这位爱慕虚荣者就谦虚地举起帽子，向小王子致意。"}, {"type": "line", "speaker": "大人", "text": "小王子心想，这比拜访的那位国王有趣。于是他又拍起巴掌来。爱慕虚荣者又举起帽子向他致意。小王子就这样做了五分钟，之后对这种单调的把戏有点厌倦了，说道。要是想让你的帽子掉下来，该怎么做呢？"}, {"type": "narr", "text": "他念到小王子的小心思，声音里带着一点忍俊不禁的温和。"}, {"type": "line", "speaker": "大人", "text": "可这回爱慕虚荣者听不进他的话，因为凡是爱慕虚荣的人，只听得进赞美的话。他问小王子道。你真的钦佩我吗？呃，钦佩是什么意思？"}, {"type": "narr", "text": "他放慢语速，把那段“钦佩”的解释念得格外清晰，像在轻轻点破什么。"}, {"type": "line", "speaker": "大人", "text": "钦佩嘛！就是承认我是星球上最美的人，服饰最好的人，最富有的人，最聪明的人。可您是您星球上唯一的人呀！让我高兴吧。请你还是来钦佩我吧。"}, {"type": "line", "speaker": "大人", "text": "小王子轻轻地耸了耸肩膀，说道。我钦佩你。可是这有什么能使你这样感兴趣的呢？于是小王子就走开了。小王子在路上自言自语地说了一句。这些大人啊！肯定是十分古怪的。"}, {"type": "narr", "text": "他念完最后一句，轻轻合上书页，眼底带着一点温和的笑意。故事里那些古怪的大人，在夜色里一个一个走远了。而那句话，大概要很久以后才会被真正读懂——这些大人啊，肯定是十分古怪的。"}]}, {"no": 133, "id": "lZrY5aFPbtU", "title": "【Lの女性向音声】小王子 十二", "title_zh": "小王子 十二", "duration": "00:01:15", "link": "https://www.youtube.com/watch?v=lZrY5aFPbtU", "enriched": true, "lines": [{"ts": "00:00:00", "text": "小王子访问的下一个星球上，住着一个酒鬼。访问时间非常短，可是却让小王子感到非常忧伤。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "你在干什么？", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "小王子问酒鬼。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "这个酒鬼默默坐在那里，面前有一堆酒瓶子，有的装着酒，有的已经空了。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "我喝酒。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "他阴沉忧郁地回答道。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "你为什么喝酒？", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "小王子问道。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "为了忘却。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "酒鬼回答。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "小王子已经有些可怜酒鬼了，他问道。", "speaker": "大人", "tone": "温柔", "sound": []}, {"ts": "00:00:00", "text": "忘却什么呢？", "speaker": "大人", "tone": "询问", "sound": []}, {"ts": "00:00:00", "text": "酒鬼垂下脑袋，坦白道。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "为了忘却我的羞愧。", "speaker": "大人", "tone": "宠溺", "sound": []}, {"ts": "00:00:00", "text": "你羞愧什么呢？", "speaker": "大人", "tone": "询问", "sound": []}, {"ts": "00:00:00", "text": "小王子很想帮助他。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "我羞愧我喝酒。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "酒鬼说完以后，就再也不开口了。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "小王子迷惑不解地离开了。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "在旅途中，他自言自语地说道。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "这些大人，确实真叫奇怪。", "speaker": "大人", "tone": "平静", "sound": []}], "scene": "朗读类（文学有声书）。小王子遇见一个喝酒的酒鬼，询问其缘由，得到的回答陷入「为忘却羞愧而喝酒、又因喝酒而羞愧」的循环。小王子困惑不解地离开。基调寓言式、怅然，主题为无意义循环。无亲密或惩罚情节。", "behaviors": [{"desc": "小王子遇见喝酒的酒鬼，询问其为何喝酒"}, {"desc": "酒鬼陷入为忘却羞愧而喝酒的循环；小王子困惑离开"}], "tone_summary": "（自动）大人视角独白，语气以平静、询问、温柔为主，题材偏现代情侣。", "genre_tags": ["现代情侣"], "genre_main": "现代情侣", "emotion_arc": "（自动）平静", "intensity": "中", "listener_role": "（自动）被大人倾诉/照顾/管教的一方（你）", "signature_elements": [], "sensitive": false, "tier": "auto", "story": [{"type": "narr", "text": "小王子访问的下一个星球上，住着一个酒鬼。访问时间非常短，却让小王子感到非常忧伤。酒鬼默默坐在那里，面前堆着一堆酒瓶子，有的装着酒，有的已经空了。"}, {"type": "line", "speaker": "小王子", "text": "你在干什么？"}, {"type": "narr", "text": "小王子问。"}, {"type": "line", "speaker": "酒鬼", "text": "我喝酒。"}, {"type": "narr", "text": "他阴沉忧郁地回答。"}, {"type": "line", "speaker": "小王子", "text": "你为什么喝酒？"}, {"type": "line", "speaker": "酒鬼", "text": "为了忘却。"}, {"type": "narr", "text": "小王子已经有些可怜他了，继续问道："}, {"type": "line", "speaker": "小王子", "text": "忘却什么呢？"}, {"type": "line", "speaker": "酒鬼", "text": "为了忘却我的羞愧。"}, {"type": "line", "speaker": "小王子", "text": "你羞愧什么呢？"}, {"type": "narr", "text": "小王子很想帮助他。"}, {"type": "line", "speaker": "酒鬼", "text": "我羞愧我喝酒。"}, {"type": "narr", "text": "酒鬼说完，就再也不开口了。小王子迷惑不解地离开了。旅途中，他自言自语地说道："}, {"type": "line", "speaker": "小王子", "text": "这些大人，确实真叫奇怪。"}]}, {"no": 134, "id": "5OuGHezuJuU", "title": "【Lの女性向音声】小王子 四", "title_zh": "小王子 四", "duration": "00:06:04", "link": "https://www.youtube.com/watch?v=5OuGHezuJuU", "enriched": true, "lines": [{"ts": "00:00:00", "text": "我还了解到一件重要的事儿。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:02", "text": "那就他老家所在星球。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:05", "text": "比一座房子大不了多少？", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:08", "text": "这倒是没有使我感到太过奇怪。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:10", "text": "我知道地球。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:13", "text": "木星火星进行这几个有名的大星星意外。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:16", "text": "还有成百个别的星球。", "speaker": "大人", "tone": "命令", "sound": []}, {"ts": "00:00:18", "text": "他们有的小的很。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:21", "text": "95万元进行也很难看见。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:24", "text": "当然一个天文学者发现了其中一颗星星。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:27", "text": "他就给他变成了一个号码。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:29", "text": "例如把他成作。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:32", "text": "325小星星。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:35", "text": "我有重要的根据认为。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:37", "text": "小王自所来自的那个星球。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:40", "text": "是小星星。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:43", "text": "B612。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:45", "text": "这颗小星星仅在1909年。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:48", "text": "被一个图尔及天文学家有望远经看见过一次。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:51", "text": "当时他曾经在一次国际天文学家代表大会上。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:54", "text": "对他的发现做了重要的论争。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:56", "text": "但由于他所穿的衣服的缘故。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:59", "text": "那时候没有人相信他。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:01:02", "text": "哪些大人就会这样？", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:01:04", "text": "幸好托尔及的一个独裁者。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:01:07", "text": "为了小星星比612的生育。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:01:10", "text": "迫使他的人民都要穿欧世服装。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:01:13", "text": "否则就出于死行。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:01:15", "text": "1920年这位天文学家穿了一身非常漂亮的服装。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:01:18", "text": "重新做了一次论证。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:01:21", "text": "这一次所有人都同意他的看法。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:01:23", "text": "我给你们讲关于小星星比612的这些细节。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:01:26", "text": "并且告诉你们他的编号。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:01:29", "text": "这是由于这些大人的缘故。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:01:31", "text": "这些大人就爱数数字。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:01:34", "text": "当你对大人们讲起你的一个新朋友时。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:01:37", "text": "他们从来不会问你一些实质性的问题。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:01:40", "text": "他们从来不讲。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:01:42", "text": "他说话声音如何。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:01:45", "text": "他喜欢什么样的游戏。", "speaker": "大人", "tone": "宠溺", "sound": []}, {"ts": "00:01:48", "text": "他是否收集互贴标本。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:01:50", "text": "他们却问你。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:01:53", "text": "他多大你年纪。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:01:56", "text": "他兄弟几个。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:01:59", "text": "他体重多少？", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:02:01", "text": "他父亲正多少钱呀！", "speaker": "大人", "tone": "撒娇", "sound": []}, {"ts": "00:02:04", "text": "他们以为这样才从了解朋友。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:02:07", "text": "如果你对大人们说。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:02:09", "text": "我看到一栋有玫瑰色的砖。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:02:12", "text": "改成了漂亮的房子。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:02:15", "text": "他的窗户上有天珠葵。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:02:17", "text": "屋顶上还有鸽子。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:02:20", "text": "他们怎么也想想不出。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:02:23", "text": "这种房子是有多美好。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:02:26", "text": "必须对他们说。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:02:28", "text": "我看见一个动物价值十万发狼的房子。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:02:31", "text": "但他们就会轻碳到。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:02:34", "text": "懂得漂亮的房子呀！", "speaker": "大人", "tone": "撒娇", "sound": []}, {"ts": "00:02:36", "text": "要是你对他们说。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:02:39", "text": "小王子存在的证据。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:02:42", "text": "就是他非常漂亮。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:02:44", "text": "他笑着。", "speaker": "大人", "tone": "宠溺", "sound": []}, {"ts": "00:02:47", "text": "想要一只羊。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:02:50", "text": "他想要一只小羊。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:02:53", "text": "这就证明他的存在。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:02:55", "text": "他们一定会送送肩膀。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:02:58", "text": "把你当作孩子看待。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:03:01", "text": "但是如果对他们说。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:03:03", "text": "小王子来自的星球。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:03:06", "text": "就是小星星必留一二。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:03:09", "text": "那么他们就会十分幸福。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:03:12", "text": "他们不会提出一大堆问题来和你纠缠。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:03:14", "text": "他们就是这样的。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:03:17", "text": "小孩子们对大人们。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:03:20", "text": "应该宽厚一些。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:03:22", "text": "不要满愿他们。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:03:25", "text": "当然。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:03:28", "text": "对我们懂得生活的人来说。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:03:30", "text": "我们才不在乎那些病好呢？", "speaker": "大人", "tone": "询问", "sound": []}, {"ts": "00:03:33", "text": "我真愿意像讲神话那样。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:03:36", "text": "来开始这个故事。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:03:39", "text": "我真想这样说。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:03:41", "text": "从前有一个小王子。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:03:44", "text": "他住在一个和他身体。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:03:47", "text": "差不多大的星球上。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:03:49", "text": "他希望有一个朋友。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:03:52", "text": "对懂得生活的人来说。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:03:55", "text": "这样说就显得很真实。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:03:58", "text": "我可不喜欢人们轻率地读我的书。", "speaker": "大人", "tone": "宠溺", "sound": []}, {"ts": "00:04:01", "text": "我在讲书这些网室的时候。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:04:05", "text": "心情是很难过的。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:04:09", "text": "我的朋友带着他的小羊已经离去六年了。", "speaker": "大人", "tone": "宠溺", "sound": []}, {"ts": "00:04:12", "text": "我之所以在这里经历把它描写出来。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:04:16", "text": "就是为了不要忘记他。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:04:20", "text": "忘记一个朋友。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:04:22", "text": "这太叫人悲伤了。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:04:25", "text": "并不是所有人都有过一个朋友。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:04:28", "text": "再说。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:04:31", "text": "我也可能变成那些大人那样。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:04:34", "text": "这对数字感兴趣。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:04:37", "text": "也正是为了这个缘故。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:04:40", "text": "我买了一颗眼料和一些牵笔。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:04:43", "text": "像我这样年纪的人。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:04:46", "text": "而且。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:04:49", "text": "除了六岁时华国闭着毒皮和开着毒皮的据忙之外。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:04:52", "text": "别的什么也没有尝试过。", "speaker": "大人", "tone": "命令", "sound": []}, {"ts": "00:04:55", "text": "现在重新再来画画。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:04:58", "text": "真的挺非击的。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:05:01", "text": "当然。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:05:04", "text": "我一定要把这些画尽量地画得逼真。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:05:07", "text": "我自己也没有把我办。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:05:07", "text": "一张画的还可以。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:05:07", "text": "另一张就不相。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:05:07", "text": "还有身材大小。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:05:07", "text": "我画得有点不准确。", "speaker": "大人", "tone": "命令", "sound": []}, {"ts": "00:05:07", "text": "在这个地方小王子画得太大了一些。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:05:07", "text": "另一个地方又画得太小了一些。", "speaker": "大人", "tone": "责备", "sound": []}, {"ts": "00:05:07", "text": "对他衣服的颜色我也拿不准。", "speaker": "大人", "tone": "命令", "sound": []}, {"ts": "00:05:07", "text": "于是我就摸索着这么？", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:05:07", "text": "吃着这么改改。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:05:07", "text": "那么改改。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:05:07", "text": "画个大概。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:05:07", "text": "我很可能在某些重要的细节上画错了。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:05:07", "text": "这就得请大家原谅我了。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:05:07", "text": "因为我这个朋友。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:05:07", "text": "从来也不想说明解释。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:05:07", "text": "他认为我同他一样。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:05:07", "text": "可成一样。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:05:07", "text": "我不能透过盒子看见笑一样。", "speaker": "大人", "tone": "宠溺", "sound": []}, {"ts": "00:05:07", "text": "我大概有点和大人差不多。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:05:07", "text": "我一定是变老了。", "speaker": "大人", "tone": "平静", "sound": []}], "scene": "朗读类（文学有声书）。叙述者介绍小王子星球的编号 B612，借机讽刺大人只重数字、不问实质的交友态度，并重申自己写作此书的缘由。随后表达对离去六年的朋友的思念，并重拾画笔为其画像。基调深情、感伤，主题为怀念与成人世界的疏离。无亲密或惩罚情节。", "behaviors": [{"desc": "叙述者介绍小王子星球编号B612，讽刺大人只重数字"}, {"desc": "叙述者表达对离去六年的朋友的思念与悲伤"}, {"desc": "叙述者重拾画笔为朋友画像，自谦画技生疏"}], "tone_summary": "（自动）大人视角独白，语气以平静、宠溺、命令为主，题材偏现代情侣。", "genre_tags": ["现代情侣"], "genre_main": "现代情侣", "emotion_arc": "（自动）平静", "intensity": "中", "listener_role": "（自动）被大人倾诉/照顾/管教的一方（你）", "signature_elements": [], "sensitive": false, "tier": "auto", "story": [{"type": "narr", "text": "夜色里，他合上书页又翻开，声音放得很轻，像在讲一个埋了很久的故事。关于那个孩子，关于他来自的那颗星球。"}, {"type": "line", "speaker": "朗读者", "text": "我还了解到一件重要的事：那就是他老家所在的星球，比一座房子大不了多少。"}, {"type": "narr", "text": "这倒没有使他感到太过奇怪。他知道，除了地球、木星、火星这些有名的大行星，还有成百个别的星球，有的小得很，用望远镜也很难看见。"}, {"type": "line", "speaker": "朗读者", "text": "一个天文学家发现了其中一颗星星，就给它编了一个号码，例如把它称作325小行星。我有重要的根据认为，小王子所来自的那个星球，是小行星B612。"}, {"type": "narr", "text": "这颗小行星只在1909年被一个土耳其天文学家望见过一次。当时他在国际天文学家代表大会上对自己的发现做了郑重的论证，可是因为他所穿的衣服的缘故，没有人相信他。"}, {"type": "line", "speaker": "朗读者", "text": "大人们就是这样。幸好，土耳其的一个独裁者，为了小行星B612的声誉，强迫他的人民都穿欧式服装，否则就处以死刑。"}, {"type": "narr", "text": "于是，1920年，这位天文学家穿了一身非常漂亮的服装，重新做了一次论证。这一次，所有人都同意了他的看法。"}, {"type": "line", "speaker": "朗读者", "text": "我之所以给你们讲关于小行星B612的这些细节，并且告诉你们它的编号，是由于这些大人的缘故——这些大人，就爱数字。"}, {"type": "narr", "text": "他顿了顿，像是想起了什么，语气里带上一点温柔的揶揄。"}, {"type": "line", "speaker": "朗读者", "text": "当你对大人们讲起你的一个新朋友时，他们从来不会问你一些实质性的问题：他说话声音如何？他喜欢什么样的游戏？他是否收集蝴蝶标本？"}, {"type": "line", "speaker": "朗读者", "text": "他们却问你：他多大年纪？兄弟几个？体重多少？他父亲挣多少钱呀？他们以为这样才算了解朋友。"}, {"type": "narr", "text": "他说，如果你告诉大人们，你看见一栋用玫瑰色砖盖成的漂亮房子，窗户上有天竺葵，屋顶上还有鸽子——他们怎么也想象不出这房子有多美好。"}, {"type": "line", "speaker": "朗读者", "text": "你必须对他们说：我看见一栋价值十万法郎的房子。那么他们就会惊叹：多么漂亮的房子呀！"}, {"type": "line", "speaker": "朗读者", "text": "要是你对他们说：小王子存在的证据，就是他非常漂亮，他笑着，想要一只羊——这就证明了他的存在。他们一定会耸耸肩膀，把你当作孩子看待。"}, {"type": "narr", "text": "他轻轻笑了一下，声音在夜色里化开。"}, {"type": "line", "speaker": "朗读者", "text": "但是，如果你对他们说：小王子来自的星球，就是小行星B612。那么他们就会十分满足，不会提出一大堆问题来和你纠缠。他们就是这样的。"}, {"type": "line", "speaker": "朗读者", "text": "小孩子们对大人们，应该宽厚一些。当然，对我们懂得生活的人来说，我们才不在乎那些编号呢。"}, {"type": "narr", "text": "他合上眼，像是要开始一个真正的童话。"}, {"type": "line", "speaker": "朗读者", "text": "我真愿意像讲神话那样来开始这个故事：从前有一个小王子，他住在一个和他身体差不多大的星球上，他希望有一个朋友。"}, {"type": "narr", "text": "他说，我可不喜欢人们轻率地读我的书。讲到这些往事的时候，他的心情是很难过的——我的朋友带着他的小羊，已经离去六年了。"}, {"type": "line", "speaker": "朗读者", "text": "我之所以在这里把他描写出来，就是为了不要忘记他。忘记一个朋友，这太叫人悲伤了。并不是所有人都有过一个朋友。"}, {"type": "narr", "text": "他说，说不定哪一天，我也会变成那些只对数字感兴趣的大人。也正是为了这个缘故，他买了一盒颜料和一些铅笔。"}, {"type": "line", "speaker": "朗读者", "text": "像我这样年纪的人，除了六岁时画过闭着肚皮和开着肚皮的蟒蛇之外，别的什么也没有尝试过。现在重新再来画画，真的挺费劲的。"}, {"type": "narr", "text": "他要把这些画尽量画得逼真，却没有把握——一张画得还可以，另一张就不行；身材大小画得不够准确，衣服的颜色也拿不准。他摸索着，这么改改，那么改改，画个大概。"}, {"type": "line", "speaker": "朗读者", "text": "我很可能在某些重要的细节上画错了，这就得请大家原谅我了。因为我这个朋友，从来也不想解释说明。他认为，我同他一样，能透过盒子看见里面的绵羊。"}, {"type": "narr", "text": "他沉默了很久，最后那句话像是说给自己听的，声音轻得几乎听不见。"}, {"type": "line", "speaker": "朗读者", "text": "我大概有点和大人差不多了。我一定是——变老了。"}]}]);